const MAGIC_DOMAINS = MAGIC_DOMAINS_DATA.filter((d) => d.selectableByMage).map((d) => d.name);
const ELEMENTAL_DOMAIN_NAMES = MAGIC_DOMAINS_DATA.filter((d) => d.elemental).map((d) => d.name);

/** Sort ou compétence obtenu automatiquement par certaines races magiques (Élémentaires, Draconoïdes),
 *  avec un aperçu au survol. Renvoie null si rien à accorder pour cette race/origine. */
/** Domaine de magie fixe accordé par la race (si applicable), indépendant de toute classe.
 *  Pour les Demi-Astralis, dépend du choix fait dans le trait "Savoir ambivalent". */
function raceMagicDomain(race, originIndex, character) {
  if (!race) return null;
  if (race.id === "elementaires") {
    if (originIndex === null || originIndex === undefined) return null;
    const origin = race.origins[originIndex];
    const map = {
      "Élémentaire de Feu": "Magie Ardente",
      "Élémentaire d’Eau": "Magie Aqueuse",
      "Élémentaire de Terre": "Magie Terrestre",
      "Élémentaire d’Air": "Magie Céleste",
    };
    return map[origin?.name] || null;
  }
  if (race.id === "draconoides") return "Magie Draconique";
  if (race.id === "demi-astralis" && character?.savoirAmbivalentChoice === "magie") {
    return character.savoirAmbivalentDomain || null;
  }
  return null;
}

const RACE_CONTROL_SPELL_NAME = {
  "Magie Ardente": "Contrôle des flammes",
  "Magie Aqueuse": "Contrôle de l’eau",
  "Magie Terrestre": "Contrôle de la terre",
  "Magie Céleste": "Contrôle de l’air",
};

/** Sort "Contrôle de ..." obtenu OBLIGATOIREMENT (pas un choix) par le trait "Contrôle de
 *  l'élément supérieur" des Élémentaires, en version améliorée (portée 15m, zone doublée). */
function raceAutoSpell(race, originIndex, character) {
  if (!race || race.id !== "elementaires") return null;
  const domain = raceMagicDomain(race, originIndex, character);
  if (!domain) return null;
  const spellName = RACE_CONTROL_SPELL_NAME[domain];
  if (!spellName) return null;
  const domainData = MAGIC_DOMAINS_DATA.find((d) => d.name === domain);
  const found = domainData ? domainData.spells.find((s) => s.nom === spellName) : null;
  const base = found || { nom: spellName, seuil: "?", portee: "?", effets: "Sort spécifique lié à votre élément (détail à préciser avec le MJ)." };
  return { nom: base.nom, seuil: base.seuil, portee: "15m", effets: base.effets + " (Version améliorée par le trait racial : portée 15m, zone d'effet doublée.)" };
}

/** Une classe donne-t-elle accès à un domaine de magie (Art de la magie) ? Mage (domaine libre
 *  ou verrouillé selon la race) et Templaris (domaine Magie Templaris, toujours verrouillé). */
function classGrantsMagic(cls) {
  return !!(cls && (cls.isMage || cls.id === "templaris"));
}

/** Domaine verrouillé (imposé, non modifiable) pour une entrée de classe donnée, selon la race
 *  du personnage. Renvoie null si le domaine reste au choix libre du joueur (cas général du Mage). */
function classLockedDomain(cls, race, character) {
  if (!cls) return null;
  if (cls.id === "templaris") return "Magie Templaris";
  if (cls.isMage) {
    if (race && race.id === "draconoides") return "Magie Draconique";
    if (race && race.id === "demi-astralis" && character?.savoirAmbivalentChoice === "magie") {
      return character.savoirAmbivalentDomain || null;
    }
  }
  return null;
}

/** Certaines races ne peuvent pas prendre la classe Templaris (leur magie est déjà exclusivement
 *  liée à un autre domaine incompatible). */
function isClassBlockedForRace(classId, race) {
  if (classId === "templaris" && race && (race.id === "draconoides" || race.id === "demi-astralis")) return true;
  return false;
}

/**
/**
 * Calcule TOUTES les compétences "Art de la magie" et les sorts associés que doit posséder
 * le personnage, en combinant race et classe(s) donnant accès à la magie (Mage, Templaris) :
 *  - Race : 1 sort choisi par le joueur, domaine imposé par la race (sauf Demi-Astralis qui
 *    choisit librement son domaine via "Savoir ambivalent").
 *  - Classe (Mage ou Templaris) : 2 sorts choisis par le joueur, domaine libre pour un Mage
 *    "normal", mais verrouillé pour les Draconoïdes (Draconique), les Demi-Astralis (leur
 *    domaine choisi à la race) et toujours pour Templaris (Magie Templaris).
 *  Si le domaine d'une classe correspond exactement au domaine de la race, les deux fusionnent
 *  visuellement en une seule compétence "Art de la magie N°2" (1 sort race + 2 sorts classe =
 *  3 sorts au total dans ce domaine). Sinon, ce sont deux compétences N°1 séparées.
 */
function computeMagicSkillGrants(character, race) {
  const classes = character.classes || [];
  const magicEntries = classes
    .map((c) => ({ entry: c, cls: CLASSES.find((x) => x.id === c.classId) }))
    .filter(({ cls, entry }) => classGrantsMagic(cls) && entry.magicDomain);
  const raceDomain = raceMagicDomain(race, character.originIndex, character);
  const raceSpellName = character.raceMagicSpellName || null;
  const skills = [];
  const spells = [];

  const RULE_TEXT = "Pour lancer un sort, lancez autant de d10 que votre niveau en Art de la magie, en ajoutant le chiffre des dizaines de votre Intelligence. Le total doit atteindre le seuil du sort. Un 9 sur un dé déclenche un Phénomène Inattendu.";

  function spellByName(domain, name) {
    if (!domain || !name) return null;
    const d = MAGIC_DOMAINS_DATA.find((x) => x.name === domain);
    return d ? d.spells.find((s) => s.nom === name) : null;
  }

  // Sort "Contrôle de ..." obligatoire des Élémentaires (indépendant du choix de sort ci-dessous).
  const autoSpell = raceAutoSpell(race, character.originIndex, character);
  if (autoSpell) spells.push({ id: "s-race-auto", ...autoSpell, grantedBy: "race-auto" });

  const mergeEntry = raceDomain ? magicEntries.find(({ entry }) => entry.magicDomain === raceDomain) : null;

  if (raceDomain && mergeEntry) {
    skills.push({
      id: "art-merged-" + mergeEntry.entry.id, nom: "Art de la magie", niveau: "2", domain: raceDomain,
      category: "Passif",
      notes: `${RULE_TEXT} Domaine : ${raceDomain}. 1 sort choisi via la race + 2 sorts choisis via la classe (voir onglet Sorts) = 3 sorts au total.`,
      grantedBy: "merged",
    });
    const sp = spellByName(raceDomain, raceSpellName);
    if (sp) spells.push({ id: "s-race", ...sp, grantedBy: "merged" });
  } else if (raceDomain) {
    skills.push({
      id: "art-race", nom: "Art de la magie", niveau: "1", domain: raceDomain,
      category: "Passif", notes: `${RULE_TEXT} Domaine : ${raceDomain}. 1 sort de catégorie 1 choisi par le joueur.`, grantedBy: "race",
    });
    const sp = spellByName(raceDomain, raceSpellName);
    if (sp) spells.push({ id: "s-race", ...sp, grantedBy: "race" });
  }

  magicEntries.forEach(({ entry }) => {
    if (mergeEntry && entry.id === mergeEntry.entry.id) return; // déjà comptée dans la fusion ci-dessus
    skills.push({
      id: "art-class-" + entry.id, nom: "Art de la magie", niveau: "1", domain: entry.magicDomain,
      category: "Passif", notes: `${RULE_TEXT} Domaine : ${entry.magicDomain}. 2 sorts de catégorie 1 gratuits (voir onglet Sorts).`, grantedBy: "class:" + entry.id,
    });
  });

  return { skills, spells };
}

/** Catégories de vitesse : portée de déplacement (m) et modificateur d'initiative (livre de
 *  règles, section "Vitesse lente/moyenne/rapide/très rapide"). */
const SPEED_CATEGORIES = {
  "Lent": { range: 5, initiativeMod: -15 },
  "Moyen": { range: 10, initiativeMod: 0 },
  "Rapide": { range: 15, initiativeMod: 10 },
  "Très rapide": { range: 20, initiativeMod: 20 },
};
/** Catégorie de vitesse effective d'un personnage : celle choisie manuellement, sinon celle
 *  imposée par un trait de race ("Très lent" chez les Mécanotrix correspond à la catégorie
 *  "Lent" du livre de règles), sinon Moyen par défaut. */
function effectiveSpeedCategory(character, race) {
  if (character.speedCategory) return character.speedCategory;
  if (race && race.id === "mecanotrix") return "Lent";
  return "Moyen";
}

