const MAX_LEVEL = 30;

/** Détermine le niveau, la progression et l'XP requise pour le niveau suivant
 *  à partir de l'XP totale du personnage (remplace l'ancien système de Rang/Puissance). */
function levelInfo(xp) {
  xp = Math.max(0, xp || 0);
  let entry = LEVEL_TABLE[0];
  for (const row of LEVEL_TABLE) {
    if (xp >= row.cumulative) entry = row; else break;
  }
  const isMax = entry.level >= MAX_LEVEL;
  const next = LEVEL_TABLE[entry.level + 1] || null;
  const xpIntoLevel = xp - entry.cumulative;
  const xpForNext = next ? next.cumulative - entry.cumulative : 0;
  return {
    level: entry.level,
    xp,
    xpIntoLevel,
    xpForNext,
    isMax,
  };
}

