    createdAt: Date.now(),
    xp: 0,
    xpSpentExtra: 0,
    pvDamage: 0,
    armor: { physique: 0, magique: 0, temporaire: 0, degatPermanent: 0 },
    destinUsed: 0,
    reputation: 0,
    corruption: 0,
    weapons: [emptyWeapon(), emptyWeapon(), emptyWeapon()],
    spells: [],
    skillsActive: [],
    skillsPassive: [],
    inventory: [],
    currency: { cuivre: 0, argent: 0, or: 0, platine: 0 },
    thematicBonuses: [],
