/** Catalogue d'équipement — fusion du catalogue de base et des objets ajoutés par le MJ,
 *  ces derniers étant partagés entre tous les utilisateurs de l'artifact. */
async function loadEquipmentCatalog() {
  try {
    const res = await window.storage.get("equipment_catalog", true);
    const shared = res ? JSON.parse(res.value) : [];
    return [...DEFAULT_EQUIPMENT_CATALOG, ...shared];
  } catch (e) {
    return DEFAULT_EQUIPMENT_CATALOG;
  }
}
async function saveEquipmentCatalog(list) {
  try {
    await window.storage.set("equipment_catalog", JSON.stringify(list), true);
  } catch (e) {
    console.error("Erreur de sauvegarde du catalogue", e);
  }
}

/** Parse un texte collé depuis Excel (TSV ou CSV) en items {nom,type,poids,prix,description}.
 *  Colonnes attendues, dans l'ordre : Nom, Type, Poids, Prix, Description. La première ligne
 *  d'en-tête est ignorée automatiquement si elle ne contient pas de nombre en colonne Poids/Prix. */
function parseEquipmentPaste(text) {
  const firstLine = text.split("\n")[0] || "";
  const sep = firstLine.includes("\t") ? "\t" : (firstLine.includes(";") ? ";" : ",");
  const lines = text.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
  const items = [];
  lines.forEach((line, i) => {
    const cols = line.split(sep).map((c) => c.trim());
    if (cols.length < 1) return;
    const [nom, type, poids, prix, ...descParts] = cols;
    if (i === 0 && isNaN(parseFloat(poids)) && isNaN(parseFloat(prix)) && /nom/i.test(nom || "")) return; // ligne d'en-tête
    if (!nom) return;
    items.push({
      id: "eq_" + Math.random().toString(36).slice(2, 9),
      nom, type: type || "Divers", poids: poids || "", prix: prix || "",
      description: descParts.join(sep) || "",
    });
  });
  return items;
}

/* ------------------------------ Hexagone ------------------------------ */

/**
 * Roue de l'hexaèdre. Affiche toujours la couche "pure" en pointillés fins ;
 * si `effectiveStats` est fourni (et différent), la couche cumulant les bonus
 * permanents + temporaires est superposée en plein, pour visualiser d'un
 * coup d'œil l'écart entre stat brute et stat effective.
 */
function HexRadar({ stats, effectiveStats = null, size = 260, onDragStat = null, onDragEffective = null }) {
  const svgRef = useRef(null);
  const cx = size / 2, cy = size / 2, r = size / 2 - 34;
  const angle = (i) => (Math.PI / 180) * (-90 + i * 60);
  const point = (i, value) => {
    const rr = (clamp(value, 0, 130) / 100) * r;
    return [cx + rr * Math.cos(angle(i)), cy + rr * Math.sin(angle(i))];
  };
  const ringPoints = (frac) => STATS.map((_, i) => point(i, frac * 100).join(",")).join(" ");
  const pureLayer = STATS.map((s, i) => point(i, stats[s.key]).join(",")).join(" ");
  const showEffective = effectiveStats && STATS.some((s) => effectiveStats[s.key] !== stats[s.key]);
  const effectiveLayer = showEffective ? STATS.map((s, i) => point(i, effectiveStats[s.key]).join(",")).join(" ") : null;

  /** Convertit une position pointeur (écran) en valeur 0-100 le long de l'axe i, en projetant
   *  sur la direction de cette pointe de l'hexaèdre. */
  function valueFromPointer(e, i) {
    const svg = svgRef.current;
    if (!svg) return null;
    const rect = svg.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * size;
    const y = ((e.clientY - rect.top) / rect.height) * size;
    const dx = x - cx, dy = y - cy;
    const proj = dx * Math.cos(angle(i)) + dy * Math.sin(angle(i));
    return Math.round(clamp((proj / r) * 100, 0, 130));
  }

  function startDrag(e, i, key, onDrag) {
    if (!onDrag) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    const move = (ev) => {
      const v = valueFromPointer(ev, i);
      if (v !== null) onDrag(key, v);
    };
    const up = (ev) => {
      e.currentTarget.removeEventListener("pointermove", move);
      e.currentTarget.removeEventListener("pointerup", up);
    };
    e.currentTarget.addEventListener("pointermove", move);
    e.currentTarget.addEventListener("pointerup", up);
    const v = valueFromPointer(e, i);
    if (v !== null) onDrag(key, v);
  }

  return (
    <svg ref={svgRef} viewBox={`0 0 ${size} ${size}`} width="100%" style={{ maxWidth: size, touchAction: onDragStat ? "none" : "auto" }}>
      {[0.25, 0.5, 0.75, 1].map((f) => (
        <polygon key={f} points={ringPoints(f)} fill="none" stroke="var(--line)" strokeWidth="1" />
      ))}
      {STATS.map((s, i) => {
        const [x, y] = point(i, 100);
        return <line key={s.key} x1={cx} y1={cy} x2={x} y2={y} stroke="var(--line)" strokeWidth="1" />;
      })}
      {showEffective && (
        <polygon points={effectiveLayer} fill="var(--accent-glow)" stroke="var(--accent)" strokeWidth="2" />
      )}
      <polygon
        points={pureLayer}
        fill={showEffective ? "none" : "var(--accent-glow)"}
        stroke={showEffective ? "var(--teal)" : "var(--accent)"}
        strokeWidth={showEffective ? "1.5" : "2"}
        strokeDasharray={showEffective ? "4 3" : "none"}
      />
      {STATS.map((s, i) => {
        const [x, y] = point(i, 116);
        return (
          <text key={s.key} x={x} y={y} fill="var(--ink-soft)" fontSize="12"
            textAnchor="middle" dominantBaseline="middle" fontFamily="var(--font-body)">
            {s.key}
          </text>
        );
      })}
      {STATS.map((s, i) => {
        const [x, y] = point(i, stats[s.key]);
        return (
          <circle key={s.key + "-dot"} cx={x} cy={y} r={onDragStat ? 8 : 4}
            fill={showEffective ? "var(--teal)" : "var(--accent)"}
            style={onDragStat ? { cursor: "grab" } : undefined}
            onPointerDown={onDragStat ? (e) => startDrag(e, i, s.key, onDragStat) : undefined}
          />
        );
      })}
      {showEffective && STATS.map((s, i) => {
        const [x, y] = point(i, effectiveStats[s.key]);
        return (
          <circle key={s.key + "-dot-eff"} cx={x} cy={y} r={onDragEffective ? 8 : 4} fill="var(--accent)"
            style={onDragEffective ? { cursor: "grab" } : undefined}
            onPointerDown={onDragEffective ? (e) => startDrag(e, i, s.key, onDragEffective) : undefined}
          />
        );
      })}
    </svg>
  );
}

/* ------------------------------ App ------------------------------ */

export default function App() {
  const [view, setView] = useState("loading"); // loading | list | wizard | sheet
  const [characters, setCharacters] = useState([]);
  const [draft, setDraft] = useState(null);
  const [step, setStep] = useState(0);
  const [activeId, setActiveId] = useState(null);
  const [toast, setToast] = useState(null);

  useEffect(() => {
    loadCharacters().then((list) => {
      setCharacters(list);
      setView("list");
    });
  }, []);

  function flashToast(msg) {
    setToast(msg);
    setTimeout(() => setToast(null), 2200);
  }

  function startCreation() {
    if (characters.length >= MAX_CHARACTERS) {
      flashToast(`Limite atteinte : ${MAX_CHARACTERS} personnages maximum. Supprimez-en un pour continuer.`);
      return;
    }
    setDraft(newCharacter());
    setStep(0);
    setView("wizard");
  }

  function startEditing(character) {
    setDraft(JSON.parse(JSON.stringify(character)));
    setStep(0);
    setView("wizard");
  }

  async function persist(list) {
    setCharacters(list);
    await saveCharacters(list);
  }

  async function commitDraft() {
    const list = [...characters.filter((c) => c.id !== draft.id), draft];
    await persist(list);
    setActiveId(draft.id);
    setView("sheet");
    flashToast("Personnage enregistré");
  }

  async function updateCharacter(id, patch) {
    const list = characters.map((c) => (c.id === id ? { ...c, ...patch } : c));
    await persist(list);
  }

  async function deleteCharacter(id) {
    const list = characters.filter((c) => c.id !== id);
    await persist(list);
    if (activeId === id) setView("list");
    flashToast("Personnage supprimé");
  }

  function openSheet(id) {
    setActiveId(id);
    setView("sheet");
  }

  const active = characters.find((c) => c.id === activeId);

  return (
    <div className="app">
      <GlobalStyle />
      <header className="topbar">
        <div className="brand">
          <HexMark />
          <div>
            <div className="brand-title">11ème Univers</div>
            <div className="brand-sub">Créateur de personnage — 2ème édition</div>
          </div>
        </div>
        {view !== "list" && (
          <button className="btn ghost" onClick={() => setView("list")}>← Mes personnages</button>
        )}
      </header>

      <main className="main">
        {view === "loading" && <div className="loading">Ouverture du grimoire…</div>}

        {view === "list" && (
          <CharacterList
            characters={characters}
            onCreate={startCreation}
            onOpen={openSheet}
            onDelete={deleteCharacter}
          />
        )}

        {view === "wizard" && draft && (
          <Wizard
            draft={draft}
            setDraft={setDraft}
            step={step}
            setStep={setStep}
            onFinish={commitDraft}
            onCancel={() => setView("list")}
          />
        )}

        {view === "sheet" && active && (
          <CharacterSheet character={active} onBack={() => setView("list")} onDelete={deleteCharacter} onUpdate={updateCharacter} onEdit={() => startEditing(active)} />
        )}
      </main>

      {toast && <div className="toast">{toast}</div>}
    </div>
  );
}

/* ------------------------------ Liste ------------------------------ */

function CharacterList({ characters, onCreate, onOpen, onDelete }) {
  const atMax = characters.length >= MAX_CHARACTERS;
  const [confirmId, setConfirmId] = useState(null);
  return (
    <div className="list-view">
      <div className="list-head">
        <div>
          <h1>Vos personnages</h1>
          <div className="count-sub">{characters.length} / {MAX_CHARACTERS} emplacements utilisés</div>
        </div>
        <button className="btn primary" onClick={onCreate} disabled={atMax} title={atMax ? "Limite de 10 personnages atteinte" : ""}>
          + Nouveau personnage
        </button>
      </div>

      {characters.length === 0 ? (
        <div className="empty">
          <p>Le grimoire est vide pour l'instant.</p>
          <p className="empty-sub">Créez votre premier héros de l'Univers pour commencer votre légende.</p>
        </div>
      ) : (
        <div className="grid">
          {characters.map((c) => {
            const race = RACES.find((r) => r.id === c.raceId);
            const classes = c.classes || [];
            const totalLevel = classes.reduce((s, e) => s + e.level, 0);
            const classSummary = classes.map((e) => {
              const cls = CLASSES.find((k) => k.id === e.classId);
              return cls?.name || "?";
            }).join(" / ");
            const confirming = confirmId === c.id;
            return (
              <div className="card" key={c.id} onClick={() => !confirming && onOpen(c.id)}>
                <div className="card-top">
                  <span className="rank-chip">Niv. {totalLevel}</span>
                  {confirming ? (
                    <span className="confirm-inline" onClick={(e) => e.stopPropagation()}>
                      <button className="btn danger small" onClick={() => { onDelete(c.id); setConfirmId(null); }}>Confirmer</button>
                      <button className="btn ghost small" onClick={() => setConfirmId(null)}>Annuler</button>
                    </span>
                  ) : (
                    <button
                      className="icon-btn"
                      title="Supprimer"
                      onClick={(e) => { e.stopPropagation(); setConfirmId(c.id); }}
                    >✕</button>
                  )}
                </div>
                <div className="card-name">{c.name || "Sans nom"}</div>
                <div className="card-meta">{race ? race.name : "Race inconnue"} · {classSummary || "Sans classe"}</div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

/* ------------------------------ Wizard ------------------------------ */

function Wizard({ draft, setDraft, step, setStep, onFinish, onCancel }) {
  const race = RACES.find((r) => r.id === draft.raceId);

  function update(patch) { setDraft({ ...draft, ...patch }); }

  const canNext = [
    !!draft.raceId,
    race ? (race.origins.length === 0 || draft.originIndex !== null) : false,
    true, // hexaèdre step always valid (budget enforced by UI)
    (draft.classes || []).length > 0,
    draft.name.trim().length > 0,
  ][step];

  return (
    <div className="wizard">
      <Stepper step={step} onJump={(i) => setStep(i)} />

      <div className="wizard-body">
        {step === 0 && (
          <StepRace draft={draft} onSelect={(id) => update({ raceId: id, originIndex: null })} />
        )}
        {step === 1 && race && (
          <StepOrigin race={race} draft={draft} onSelect={(i) => update({
            originIndex: i, raceMagicSpellName: null,
            spells: (draft.spells || []).filter((s) => s.grantedBy !== "race" && s.grantedBy !== "merged"),
          })} />
        )}
        {step === 2 && (
          <StepHexaedre draft={draft} race={race} onChange={(stats) => update({ stats })} />
        )}
        {step === 3 && (
          <StepClasses draft={draft} race={race} onChange={update} />
        )}
        {step === 4 && (
          <StepIdentity draft={draft} onChange={(patch) => update(patch)} />
        )}
        {step === 5 && (
          <StepReview draft={draft} race={race} onChange={update} />
        )}
      </div>

      <div className="wizard-nav">
        <button className="btn ghost" onClick={() => (step === 0 ? onCancel() : setStep(step - 1))}>
          {step === 0 ? "Annuler" : "Précédent"}
        </button>
        {step < STEPS.length - 1 ? (
          <button className="btn primary" disabled={!canNext} onClick={() => setStep(step + 1)}>Suivant</button>
        ) : (
          <button className="btn primary" onClick={onFinish}>Terminer et enregistrer</button>
        )}
      </div>
    </div>
  );
}

function Stepper({ step, onJump }) {
  return (
    <div className="stepper">
      {STEPS.map((label, i) => (
        <div
          key={label}
          className={"step-pill" + (i === step ? " active" : "") + (i < step ? " done" : "")}
          onClick={() => onJump(i)}
        >
          <span className="step-dot" />{label}
        </div>
      ))}
    </div>
  );
}

function StepRace({ draft, onSelect }) {
  function pickRandom() {
    const r = RACES[Math.floor(Math.random() * RACES.length)];
    onSelect(r.id);
  }
  function pickRandomWeighted() {
    const total = RACES.reduce((sum, r) => sum + r.percent, 0);
    let roll = Math.random() * total;
    for (const r of RACES) {
      roll -= r.percent;
      if (roll <= 0) { onSelect(r.id); return; }
    }
    onSelect(RACES[RACES.length - 1].id);
  }

  return (
    <div>
      <h2>Choisissez une race</h2>
      <p className="hint">Chaque race apporte deux traits positifs, un trait négatif, et détermine vos origines possibles.</p>
      <div className="race-random-row">
        <button className="btn ghost small" onClick={pickRandom}>🎲 Aléatoire</button>
        <button className="btn ghost small" onClick={pickRandomWeighted}>🎲 Aléatoire proportionnel</button>
      </div>
      <div className="race-grid">
        {RACES.map((r) => (
          <div
            key={r.id}
            className={"race-card" + (draft.raceId === r.id ? " selected" : "")}
            onClick={() => onSelect(r.id)}
          >
            <div className="race-card-head">
              <span className="race-name">{r.name}</span>
            </div>
            <p className="race-flavor">{r.flavor}</p>
            {!r.complete && <span className="badge-todo">Détails à compléter</span>}
          </div>
        ))}
      </div>
      {draft.raceId && (
        <TraitList race={RACES.find((r) => r.id === draft.raceId)} originIndex={draft.originIndex} />
      )}
    </div>
  );
}

function TraitList({ race, character, onChange, layers, originIndex }) {
  const [changingSpell, setChangingSpell] = useState(false);
  if (!race.traits.length) {
    return <p className="hint">Les traits de {race.name} n'ont pas encore été saisis dans le compendium.</p>;
  }
  const canActivate = !!(character && onChange && layers);
  const raceDomain = character ? raceMagicDomain(race, originIndex, character) : null;
  const raceSpellName = character?.raceMagicSpellName || null;
  const domainData = raceDomain ? MAGIC_DOMAINS_DATA.find((d) => d.name === raceDomain) : null;
  const knownSpellNames = new Set([
    ...((character?.spells || []).map((s) => s.nom)),
    ...((character?.classes || []).flatMap((c) => (c.freeSpells || []).map((s) => s.nom))),
  ]);
  const availableSpells = domainData ? domainData.spells.filter((sp) => sp.nom === raceSpellName || !knownSpellNames.has(sp.nom)) : [];

  /** Choix direct et immédiat du sort racial : met à jour raceMagicSpellName ET la liste de
   *  sorts en un seul appel (pas de dépendance à une synchronisation asynchrone séparée). */
  function selectRaceSpell(sp) {
    const alreadyPicked = raceSpellName === sp.nom;
    const newName = alreadyPicked ? null : sp.nom;
    const otherSpells = (character.spells || []).filter((s) => s.grantedBy !== "race" && s.grantedBy !== "merged");
    const newSpells = newName
      ? [...otherSpells, { id: "s" + Math.random().toString(36).slice(2, 9), nom: sp.nom, seuil: sp.seuil, portee: sp.portee, effets: sp.effets, grantedBy: "race" }]
      : otherSpells;
    onChange({ raceMagicSpellName: newName, spells: newSpells });
    setChangingSpell(false);
  }

  function toggleMechanic(traitName, mech) {
    const toggles = character.activeToggles || {};
    const isOn = !!toggles[traitName];
    const temp = { ...(character.tempBonuses || emptyBonuses()) };
    const armor = { ...(character.armor || { physique: 0, magique: 0, temporaire: 0 }) };

    if (mech.kind === "toggle") {
      const dir = isOn ? -1 : 1;
      Object.entries(mech.statDeltas || {}).forEach(([stat, amt]) => { temp[stat] = (temp[stat] || 0) + dir * amt; });
      if (mech.armorDelta) armor.temporaire = Math.max(0, (armor.temporaire || 0) + dir * mech.armorDelta);
      onChange({ tempBonuses: temp, armor, activeToggles: { ...toggles, [traitName]: !isOn } });
    } else if (mech.kind === "pulse") {
      if (!isOn) {
        // Activation : toutes les stats passent à 90% (delta calculé depuis le permanent actuel)
        STATS.forEach((s) => { temp[s.key] = 90 - layers[s.key].permanent; });
        onChange({ tempBonuses: temp, activeToggles: { ...toggles, [traitName]: true, [traitName + ":fatigue"]: false } });
      } else {
        // Désactivation : fatigue, stats divisées par deux, jusqu'au prochain repos
        STATS.forEach((s) => { temp[s.key] = -Math.round(layers[s.key].permanent / 2); });
        onChange({ tempBonuses: temp, activeToggles: { ...toggles, [traitName]: false, [traitName + ":fatigue"]: true } });
      }
    }
  }

  function useDaily(traitName, mech) {
    const uses = character.dailyUses || {};
    const used = uses[traitName] || 0;
    if (used >= mech.usesPerDay) return;
    const temp = { ...(character.tempBonuses || emptyBonuses()) };
    Object.entries(mech.statDeltas || {}).forEach(([stat, amt]) => { temp[stat] = (temp[stat] || 0) + amt; });
    onChange({ tempBonuses: temp, dailyUses: { ...uses, [traitName]: used + 1 } });
  }

  return (
    <div className="trait-list">
      {race.traits.map((t) => {
        const mech = RACE_TRAIT_MECHANICS[t.name];
        const isMagicGrantTrait = t.name === "Nature élémentaire" || t.name === "Magie draconique";
        const isSavoirAmbivalent = t.name === "Savoir ambivalent";
        const toggles = (character && character.activeToggles) || {};
        const isOn = !!toggles[t.name];
        return (
          <div key={t.name} className={"trait " + t.type}>
            <span className="trait-name">{t.name}</span>
            <span className="trait-tag">{t.type === "positif" ? "Bonus" : "Malus"}</span>
            {t.actionType && t.actionType !== "Passif" && (
              <span className="trait-action-tag">{t.actionType}</span>
            )}
            <p>{t.desc}</p>

            {isMagicGrantTrait && canActivate && raceDomain && (
              <div className="trait-mechanic">
                {raceSpellName && !changingSpell ? (
                  <div className="spell-chosen-summary">
                    <span className="hint small" style={{ margin: 0 }}>
                      Domaine : <strong>{raceDomain}</strong>. Sort choisi : <strong>{raceSpellName}</strong>
                    </span>
                    <button type="button" className="btn ghost small" onClick={() => setChangingSpell(true)}>Changer de sort</button>
                  </div>
                ) : (
                  <>
                    <p className="hint small" style={{ margin: "0 0 6px" }}>
                      Domaine : <strong>{raceDomain}</strong>. Choisissez votre sort de catégorie 1 gratuit.
                    </p>
                    {domainData && availableSpells.length > 0 ? (
                      <div className="spell-pick-grid">
                        {availableSpells.map((sp) => {
                          const picked = raceSpellName === sp.nom;
                          return (
                            <div key={sp.nom} className={"spell-pick-card" + (picked ? " picked" : "")}>
                              <div className="spell-pick-head">
                                <span className="spell-pick-name">{sp.nom}</span>
                                <span className="spell-pick-seuil">Seuil {sp.seuil}</span>
                              </div>
                              <div className="spell-pick-portee">Portée : {sp.portee}</div>
                              <p className="spell-pick-desc">{sp.effets}</p>
                              <button type="button" className={"btn small" + (picked ? " primary" : " ghost")} onClick={() => selectRaceSpell(sp)}>
                                {picked ? "✓ Sort choisi" : "Choisir ce sort"}
                              </button>
                            </div>
                          );
                        })}
                      </div>
                    ) : (
                      <p className="hint small">{domainData ? "Tous les sorts de catégorie 1 de ce domaine sont déjà connus." : "Sorts de catégorie 1 pas encore rédigés pour ce domaine."}</p>
                    )}
                  </>
                )}
              </div>
            )}
            {isMagicGrantTrait && !canActivate && (
              <p className="hint small">Le choix du sort gratuit se fait depuis la fiche du personnage.</p>
            )}

            {isSavoirAmbivalent && canActivate && (
              <div className="trait-mechanic">
                <p className="hint small" style={{ margin: "0 0 6px" }}>Choisissez une compétence :</p>
                <div className="chip-row">
                  {[["magie", "Art de la Magie N°1"], ["martial", "Art martial N°1"], ["diplomatie", "Art de la diplomatie"]].map(([val, label]) => (
                    <button key={val} className={"chip" + (character.savoirAmbivalentChoice === val ? " selected" : "")}
                      onClick={() => onChange({ savoirAmbivalentChoice: character.savoirAmbivalentChoice === val ? null : val, savoirAmbivalentDomain: null, raceMagicSpellName: null })}>
                      {label}
                    </button>
                  ))}
                </div>
                {character.savoirAmbivalentChoice === "magie" && (
                  <div style={{ marginTop: 10 }}>
                    <p className="hint small">Choisissez librement un domaine de magie :</p>
                    <div className="chip-row">
                      {MAGIC_DOMAINS.map((d) => (
                        <button key={d} className={"chip" + (character.savoirAmbivalentDomain === d ? " selected" : "")}
                          onClick={() => onChange({
                            savoirAmbivalentDomain: d, raceMagicSpellName: null,
                            spells: (character.spells || []).filter((s) => s.grantedBy !== "race" && s.grantedBy !== "merged"),
                          })}>{d}</button>
                      ))}
                    </div>
                    {raceDomain && domainData && (
                      raceSpellName && !changingSpell ? (
                        <div className="spell-chosen-summary" style={{ marginTop: 10 }}>
                          <span className="hint small" style={{ margin: 0 }}>Sort choisi : <strong>{raceSpellName}</strong></span>
                          <button type="button" className="btn ghost small" onClick={() => setChangingSpell(true)}>Changer de sort</button>
                        </div>
                      ) : (
                        <div className="spell-pick-grid" style={{ marginTop: 10 }}>
                          {availableSpells.map((sp) => {
                            const picked = raceSpellName === sp.nom;
                            return (
                              <div key={sp.nom} className={"spell-pick-card" + (picked ? " picked" : "")}>
                                <div className="spell-pick-head">
                                  <span className="spell-pick-name">{sp.nom}</span>
                                  <span className="spell-pick-seuil">Seuil {sp.seuil}</span>
                                </div>
                                <p className="spell-pick-desc">{sp.effets}</p>
                                <button type="button" className={"btn small" + (picked ? " primary" : " ghost")} onClick={() => selectRaceSpell(sp)}>
                                  {picked ? "✓ Sort choisi" : "Choisir ce sort"}
                                </button>
                              </div>
                            );
                          })}
                          {availableSpells.length === 0 && <p className="hint small">Tous les sorts de catégorie 1 de ce domaine sont déjà connus.</p>}
                        </div>
                      )
                    )}
                  </div>
                )}
              </div>
            )}

            {mech && (
              <div className="trait-mechanic">
                <p className="hint small" style={{ margin: "0 0 6px" }}>{mech.note}</p>
                {!canActivate ? (
                  <p className="hint small">Activable depuis la fiche du personnage.</p>
                ) : mech.kind === "toggle" ? (
                  <label className="trait-toggle">
                    <input type="checkbox" checked={isOn} onChange={() => toggleMechanic(t.name, mech)} /> Activer
                  </label>
                ) : mech.kind === "pulse" ? (
                  <label className="trait-toggle">
                    <input type="checkbox" checked={isOn} onChange={() => toggleMechanic(t.name, mech)} />
                    {isOn ? "Désactiver (déclenche la fatigue)" : "Activer"}
                    {toggles[t.name + ":fatigue"] && <span className="trait-fatigue-tag"> Fatigué·e (jusqu'au repos)</span>}
                  </label>
                ) : mech.kind === "daily" ? (
                  <div className="trait-daily-row">
                    {Array.from({ length: mech.usesPerDay }).map((_, i) => {
                      const used = (character?.dailyUses || {})[t.name] || 0;
                      const checked = i < used;
                      return (
                        <input
                          key={i} type="checkbox" checked={checked}
                          onChange={() => {
                            const uses = character.dailyUses || {};
                            const current = uses[t.name] || 0;
                            if (checked) {
                              // décocher = annuler la dernière utilisation (retire le bonus)
                              const temp = { ...(character.tempBonuses || emptyBonuses()) };
                              Object.entries(mech.statDeltas || {}).forEach(([stat, amt]) => { temp[stat] = (temp[stat] || 0) - amt; });
                              onChange({ tempBonuses: temp, dailyUses: { ...uses, [t.name]: Math.max(0, current - 1) } });
                            } else {
                              useDaily(t.name, mech);
                            }
                          }}
                        />
                      );
                    })}
                    <span className="hint small" style={{ margin: 0 }}>{mech.usesPerDay - ((character?.dailyUses || {})[t.name] || 0)} / {mech.usesPerDay} restant(s) aujourd'hui</span>
                  </div>
                ) : null}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function StepOrigin({ race, draft, onSelect }) {
  if (!race.origins.length) {
    return (
      <div>
        <h2>Origine</h2>
        <p className="hint">Aucune origine n'est encore renseignée pour {race.name} dans le compendium. Vous pouvez passer cette étape.</p>
      </div>
    );
  }
  return (
    <div>
      <h2>Choisissez une origine</h2>
      <p className="hint">L'origine ancre votre personnage dans le monde et offre un bonus de statistique ainsi que deux avantages.</p>
      <div className="origin-grid">
        {race.origins.map((o, i) => (
          <div key={o.name} className={"origin-card" + (draft.originIndex === i ? " selected" : "")} onClick={() => onSelect(i)}>
            <div className="origin-head">
              <span>{o.name}</span>
              <span className="origin-bonus">{originStatLabel(o)}</span>
            </div>
            {o.flavor && <p className="hint small" style={{ margin: "4px 0 8px" }}>{o.flavor}</p>}
            <ul>{o.bonuses.map((b) => <li key={b}>{b}</li>)}</ul>
          </div>
        ))}
      </div>
    </div>
  );
}

function StepHexaedre({ draft, race, onChange }) {
  const pool = 180 + (race?.bonusPool || 0);
  const allocated = useMemo(
    () => STATS.reduce((sum, s) => sum + (draft.stats[s.key] - 10), 0),
    [draft.stats]
  );
  const remaining = pool - allocated;

  function setStat(key, value) {
    const current = draft.stats[key];
    const delta = value - current;
    if (delta > 0 && delta > remaining) return;
    const next = { ...draft.stats, [key]: clamp(value, 10, 95) };
    onChange(next);
  }

  const layers = computeStatLayers(draft, race);
  const permanentStats = {};
  STATS.forEach((s) => (permanentStats[s.key] = layers[s.key].permanent));
  const origin = race && draft.originIndex !== null ? race.origins[draft.originIndex] : null;

  return (
    <div>
      <h2>Répartissez l'hexaèdre</h2>
      <p className="hint">
        Chaque pointe part de 10% (valeur non modifiable). Vous disposez de <strong>{pool}%</strong> à répartir
        {race?.bonusPool ? ` (dont ${race.bonusPool}% grâce au trait de race)` : ""}. Maximum 95% par statistique.
        {origin ? ` Le bonus d'origine (${originStatLabel(origin)}) est un bonus permanent : il s'ajoute par-dessus, hors budget.` : ""}
      </p>
      <div className="hex-layout">
        <HexRadar stats={draft.stats} effectiveStats={origin ? permanentStats : null} onDragStat={setStat} />
        <div className="hex-controls">
          <div className={"pool-display" + (remaining < 0 ? " over" : "")}>
            Points restants : <strong>{remaining}</strong> / {pool}
          </div>
          {STATS.map((s) => (
            <div className="stat-row" key={s.key}>
              <div className="stat-label">
                <span className="stat-key">{s.key}</span>
                <span className="stat-name">{s.name}</span>
              </div>
              <input
                type="range" min="10" max="95" value={draft.stats[s.key]}
                onChange={(e) => setStat(s.key, parseInt(e.target.value, 10))}
              />
              <span className="stat-value">
                {draft.stats[s.key]}%
                {layers[s.key].permBonus > 0 && (
                  <span className="stat-bonus-tag"> → {layers[s.key].permanent}%{layers[s.key].critBonus > 0 ? ` (+${layers[s.key].critBonus}% RC)` : ""}</span>
                )}
              </span>
            </div>
          ))}
          <p className="hint small">
            PV max estimés : <strong>{layers.CON.permanent}</strong> · Régénération/nuit : <strong>{Math.floor(layers.CON.permanent / 10)}</strong> · Initiative : 1d100 + {layers.AGI.permanent}
          </p>
          {origin && <p className="hint small">Trait plein en pointillé teal = stat pure · zone dorée pleine = stat pure + bonus permanent d'origine.</p>}
        </div>
      </div>
    </div>
  );
}

function StepClasses({ draft, race, onChange }) {
  const classes = draft.classes || [];
  const [pickerOpen, setPickerOpen] = useState(false);
  const [expandedId, setExpandedId] = useState(null);
  const totalLevel = classes.reduce((s, c) => s + c.level, 0);
  const hasElementalAffinity = race && race.id === "elementaires";

  function addClass(classId) {
    const entry = emptyClassEntry(classId);
    onChange({ classes: [...classes, entry] });
    setPickerOpen(false);
    setExpandedId(entry.id);
  }
  function updateEntry(id, patch) {
    onChange({ classes: classes.map((c) => (c.id === id ? { ...c, ...patch } : c)) });
  }
  function removeEntry(id) {
    onChange({ classes: classes.filter((c) => c.id !== id) });
    if (expandedId === id) setExpandedId(null);
  }

  return (
    <div>
      <h2>Choisissez vos classes</h2>
      <p className="hint">
        Ajoutez une ou plusieurs classes pour multiclasser dès la création, et choisissez le niveau de départ de chacune.
        Niveau total actuel : <strong>{totalLevel}</strong>.
      </p>

      <div className="class-entries">
        {classes.map((entry) => (
          <ClassEntryCard
            key={entry.id}
            entry={entry}
            race={race}
            draft={draft}
            hasElementalAffinity={hasElementalAffinity}
            expanded={expandedId === entry.id}
            onToggleExpand={() => setExpandedId(expandedId === entry.id ? null : entry.id)}
            onUpdate={(patch) => updateEntry(entry.id, patch)}
            onRemove={() => removeEntry(entry.id)}
          />
        ))}

        <button className="add-class-tile" onClick={() => setPickerOpen(true)}>
          <span className="add-class-plus">+</span>
          <span>Ajouter une classe</span>
        </button>
      </div>

      {pickerOpen && (
        <div className="class-picker-overlay" onClick={() => setPickerOpen(false)}>
          <div className="class-picker" onClick={(e) => e.stopPropagation()}>
            <h3>Choisir une classe</h3>
            <p className="hint small">Une classe déjà possédée se monte en niveau depuis sa carte, elle ne réapparaît pas ici.</p>
            <div className="class-picker-grid">
              {CLASSES.filter((c) => !classes.some((e) => e.classId === c.id) && !isClassBlockedForRace(c.id, race)).map((c) => (
                <button key={c.id} className="class-picker-card" onClick={() => addClass(c.id)}>
                  <ClassIcon classId={c.id} size={32} />
                  <span>{c.name}</span>
                </button>
              ))}
            </div>
            {race && (race.id === "draconoides" || race.id === "demi-astralis") && (
              <p className="hint small" style={{ marginTop: 8 }}>La classe Templaris n'est pas accessible à votre race (magie incompatible).</p>
            )}
            <button className="btn ghost small" onClick={() => setPickerOpen(false)}>Annuler</button>
          </div>
        </div>
      )}
    </div>
  );
}

function ClassEntryCard({ entry, race, draft, hasElementalAffinity, expanded, onToggleExpand, onUpdate, onRemove }) {
  const [magicOpen, setMagicOpen] = useState(false);
  const [changingSpells, setChangingSpells] = useState(false);
  const cls = CLASSES.find((c) => c.id === entry.classId);
  const levelData = cls ? CLASS_LEVELS[cls.id] : null;
  const subclassInfo = levelData && levelData.ranks
    ? levelData.ranks.subclasses.find((s) => s.name === entry.subclass)
    : null;
  const domainData = MAGIC_DOMAINS_DATA.find((d) => d.name === entry.magicDomain);
  const freeSpells = entry.freeSpells || [];
  const grantsMagic = classGrantsMagic(cls);
  const lockedDomain = classLockedDomain(cls, race, draft);
  const maxFreeSpells = 2;
  const unlockedActions = buildActionList(entry.classId, entry.subclass, entry.level);
  const futureActions = buildActionListFull(entry.classId, entry.subclass).filter((a) => a.unlockLevel > entry.level);
  const subclassUnlocked = entry.level >= 6;
  const magicMissing = grantsMagic && !entry.magicDomain && !lockedDomain;
  const knownSpellNamesElsewhere = new Set([
    ...((draft?.spells || []).map((s) => s.nom)),
    ...((draft?.classes || []).filter((c) => c.id !== entry.id).flatMap((c) => (c.freeSpells || []).map((s) => s.nom))),
  ]);
  const availableClassSpells = domainData ? domainData.spells.filter((sp) => freeSpells.some((f) => f.nom === sp.nom) || !knownSpellNamesElsewhere.has(sp.nom)) : [];

  useEffect(() => {
    if (lockedDomain && entry.magicDomain !== lockedDomain) {
      onUpdate({ magicDomain: lockedDomain, freeSpells: [] });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lockedDomain]);

  function toggleFreeSpell(spell) {
    const already = freeSpells.some((s) => s.nom === spell.nom);
    if (already) onUpdate({ freeSpells: freeSpells.filter((s) => s.nom !== spell.nom) });
    else if (freeSpells.length < maxFreeSpells) onUpdate({ freeSpells: [...freeSpells, spell] });
    if (freeSpells.length + (already ? -1 : 1) >= maxFreeSpells) setChangingSpells(false);
  }

  return (
    <div className="class-entry-card">
      <div className="class-entry-head">
        <ClassIcon classId={entry.classId} size={36} />
        <div className="class-entry-title">
          <div className="class-entry-name">{cls?.name || "Classe"}</div>
          {entry.subclass && <div className="class-entry-subname">{entry.subclass}</div>}
        </div>
        <div className="class-entry-level">
          <button className="btn ghost small" onClick={() => onUpdate({ level: clamp(entry.level - 1, 1, MAX_LEVEL) })}>−</button>
          <span>Niv. {entry.level}</span>
          <button className="btn ghost small" onClick={() => onUpdate({ level: clamp(entry.level + 1, 1, MAX_LEVEL) })}>+</button>
        </div>
        <button className="icon-btn" title="Retirer cette classe" onClick={onRemove}>✕</button>
      </div>

      {cls && cls.subclasses.length > 0 && (
        <div className="subclass-block">
          {!entry.subclass ? (
            <>
              <h3>École / Sous-classe {!subclassUnlocked && <span className="hint small">(disponible à partir du niveau 6 — niveau actuel : {entry.level})</span>}</h3>
              <div className="subclass-preview-grid">
                {cls.subclasses.map((s) => {
                  const info = levelData && levelData.ranks ? levelData.ranks.subclasses.find((x) => x.name === s) : null;
                  return (
                    <div
                      key={s}
                      className={"subclass-preview-card selectable" + (!subclassUnlocked ? " locked" : "")}
                      onClick={() => subclassUnlocked && onUpdate({ subclass: s })}
                    >
                      <div className="subclass-preview-name">{s}{!subclassUnlocked && " 🔒"}</div>
                      {info?.flavor && <p className="hint small">{info.flavor}</p>}
                    </div>
                  );
                })}
              </div>
            </>
          ) : (
            <>
              <div className="subclass-chosen-head">
                <h3 style={{ margin: 0 }}>{entry.subclass}</h3>
                <button className="btn ghost small" onClick={() => onUpdate({ subclass: null })}>Changer d'école</button>
              </div>
              {subclassInfo?.flavor && <p className="hint">{subclassInfo.flavor}</p>}
              {subclassInfo?.equipment && <p className="hint small"><strong>Équipement de départ :</strong> {subclassInfo.equipment}</p>}

              {futureActions.length > 0 && (
                <>
                  <h3>Évolutions futures</h3>
                  <div className="level-table">
                    {futureActions.map((a, i) => (
                      <div className="level-row locked-preview" key={i}>
                        <span className="level-num">{a.source}</span>
                        <span className="level-name">{a.name}</span>
                        <span className="level-type">{a.type}</span>
                        <p className="level-desc">{a.desc}</p>
                      </div>
                    ))}
                  </div>
                </>
              )}
            </>
          )}
        </div>
      )}

      {grantsMagic && (
        <div className="level-click-row" style={{ marginTop: 10 }}>
          <button className={"level-click-pill" + (magicMissing ? " warn" : "")} onClick={() => setMagicOpen((v) => !v)}>
            Niveau 1 : Première configuration {magicMissing ? "⚠ à choisir" : "✓"}
          </button>
          {magicMissing && <span className="hint small level-click-hint">Cliquez pour choisir votre domaine de magie et vos 2 sorts gratuits (vous pouvez continuer sans, mais pensez-y).</span>}
        </div>
      )}

      {grantsMagic && magicOpen && (
        <div className="subclass-block">
          <h3>Domaine de magie</h3>
          {hasElementalAffinity && !lockedDomain && (
            <p className="hint small domain-affinity">✦ Affinité raciale : votre race (Élémentaires) est naturellement liée aux magies élémentaires.</p>
          )}
          {lockedDomain ? (
            <p className="hint small domain-locked">🔒 Domaine verrouillé : <strong>{lockedDomain}</strong> ({cls.id === "templaris" ? "la classe Templaris impose ce domaine" : "votre race ne permet pas de choisir un autre domaine en tant que Mage"}).</p>
          ) : (
            <div className="chip-row">
              {MAGIC_DOMAINS.map((d) => {
                const isElemental = ELEMENTAL_DOMAIN_NAMES.includes(d);
                return (
                  <button key={d} className={"chip" + (entry.magicDomain === d ? " selected" : "") + (hasElementalAffinity && isElemental ? " affinity" : "")} onClick={() => onUpdate({ magicDomain: d, freeSpells: [] })}>
                    {d}{hasElementalAffinity && isElemental ? " ✦" : ""}
                  </button>
                );
              })}
            </div>
          )}
          {domainData && (
            <div className="domain-panel">
              {domainData.restricted && <p className="hint small domain-restricted">⚠ Domaine restreint : {domainData.restricted}</p>}
              {domainData.flavor && <p className="hint">{domainData.flavor}</p>}
              {freeSpells.length >= maxFreeSpells && !changingSpells ? (
                <div className="spell-chosen-summary">
                  <span className="hint small" style={{ margin: 0 }}>Sorts choisis : <strong>{freeSpells.map((s) => s.nom).join(", ")}</strong></span>
                  <button type="button" className="btn ghost small" onClick={() => setChangingSpells(true)}>Changer</button>
                </div>
              ) : domainData.spells.length > 0 ? (
                <>
                  <p className="hint small">
                    Choisissez {maxFreeSpells} sorts de catégorie 1 gratuits ({freeSpells.length} / {maxFreeSpells}).
                    {lockedDomain && " Ce choix vient s'ajouter au sort déjà obtenu via le trait racial : même domaine, mais la compétence passe en Art de la magie N°2."}
                  </p>
                  <div className="spell-pick-grid">
                    {availableClassSpells.map((sp) => {
                      const picked = freeSpells.some((s) => s.nom === sp.nom);
                      const disabled = !picked && freeSpells.length >= maxFreeSpells;
                      return (
                        <div key={sp.nom} className={"spell-pick-card" + (picked ? " picked" : "") + (disabled ? " disabled" : "")} onClick={() => !disabled && toggleFreeSpell(sp)}>
                          <div className="spell-pick-head">
                            <span className="spell-pick-name">{sp.nom}</span>
                            <span className="spell-pick-seuil">Seuil {sp.seuil}</span>
                          </div>
                          <div className="spell-pick-portee">Portée : {sp.portee}</div>
                          <p className="spell-pick-desc">{sp.effets}</p>
                        </div>
                      );
                    })}
                    {availableClassSpells.length === 0 && <p className="hint small">Tous les sorts de catégorie 1 de ce domaine sont déjà connus.</p>}
                  </div>
                </>
              ) : (
                <p className="hint small">Sorts de catégorie 1 pas encore rédigés pour ce domaine.</p>
              )}
            </div>
          )}
        </div>
      )}

      <button className="btn ghost small" onClick={onToggleExpand} style={{ marginTop: 10 }}>
        {expanded ? "− Masquer les informations" : "+ Plus d'informations (techniques débloquées au niveau actuel)"}
      </button>

      {expanded && (
        <div className="class-entry-expand">
          <h3>Débloqué au niveau {entry.level}</h3>
          {unlockedActions.length > 0 ? (
            <div className="level-table">
              {unlockedActions.map((a, i) => (
                <div className="level-row" key={i}>
                  <span className="level-num">{a.source}</span>
                  <span className="level-name">{a.name}</span>
                  <span className="level-type">{a.type}</span>
                  <p className="level-desc">{a.desc}</p>
                </div>
              ))}
            </div>
          ) : <p className="hint small">Rien débloqué pour le moment.</p>}
        </div>
      )}
    </div>
  );
}

function StepIdentity({ draft, onChange }) {
  function onPhotoChange(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => onChange({ photo: reader.result });
    reader.readAsDataURL(file);
  }

  return (
    <div>
      <h2>Identité du personnage</h2>
      <div className="identity-layout">
        <div className="identity-photo-block">
          <div className="identity-photo">
            {draft.photo ? <img src={draft.photo} alt="Portrait" /> : <span className="identity-photo-placeholder">Portrait</span>}
          </div>
          <label className="btn ghost small identity-photo-btn">
            {draft.photo ? "Changer la photo" : "Ajouter une photo"}
            <input type="file" accept="image/*" onChange={onPhotoChange} style={{ display: "none" }} />
          </label>
          {draft.photo && <button className="btn ghost small" onClick={() => onChange({ photo: null })}>Retirer</button>}
        </div>

        <div className="identity-form">
          <label>Nom
            <input type="text" value={draft.name} placeholder="Ex : Titania LaRouge"
              onChange={(e) => onChange({ name: e.target.value })} />
          </label>
          <div className="identity-grid">
            <label>Sexe
              <input type="text" value={draft.sexe || ""} onChange={(e) => onChange({ sexe: e.target.value })} />
            </label>
            <label>Âge
              <input type="text" value={draft.age || ""} onChange={(e) => onChange({ age: e.target.value })} />
            </label>
            <label>Taille
              <input type="text" value={draft.taille || ""} placeholder="ex : 1m75" onChange={(e) => onChange({ taille: e.target.value })} />
            </label>
            <label>Poids
              <input type="text" value={draft.poids || ""} placeholder="ex : 68kg" onChange={(e) => onChange({ poids: e.target.value })} />
            </label>
            <label>Cheveux
              <input type="text" value={draft.cheveux || ""} onChange={(e) => onChange({ cheveux: e.target.value })} />
            </label>
            <label>Yeux
              <input type="text" value={draft.yeux || ""} onChange={(e) => onChange({ yeux: e.target.value })} />
            </label>
          </div>
        </div>
      </div>
    </div>
  );
}

function StepReview({ draft, race, onChange }) {
  return (
    <div>
      <h2>Résumé</h2>
      <p className="hint small">Vous pouvez déjà renseigner armes, sorts, compétences et inventaire ici — tout reste modifiable après enregistrement.</p>
      <CharacterTabs character={draft} race={race} onChange={onChange} />
    </div>
  );
}

/* ------------------------------ Fiche à onglets ------------------------------ */

function CharacterSheet({ character, onBack, onDelete, onUpdate, onEdit }) {
  const race = RACES.find((r) => r.id === character.raceId);
  const [confirmDelete, setConfirmDelete] = useState(false);

  return (
    <div className="sheet-view">
      <div className="sheet-actions">
        <button className="btn ghost" onClick={onBack}>← Retour</button>
        <div className="sheet-actions-right">
          <button className="btn ghost" onClick={onEdit}>✎ Modifier (retour à la création)</button>
          {confirmDelete ? (
            <span className="confirm-inline">
              <button className="btn danger" onClick={() => onDelete(character.id)}>Confirmer la suppression</button>
              <button className="btn ghost" onClick={() => setConfirmDelete(false)}>Annuler</button>
            </span>
          ) : (
            <button className="btn danger" onClick={() => setConfirmDelete(true)}>Supprimer</button>
          )}
        </div>
      </div>
      <CharacterTabs character={character} race={race} onChange={(patch) => onUpdate(character.id, patch)} />
    </div>
  );
}

const SHEET_TABS = ["Aperçu", "Compétences", "Sorts", "Alcoolémie", "Inventaire", "Notes"];

/** Le personnage a-t-il débloqué la mécanique d'Alcoolémie (Mercenaire — Groupe des Trois Futs,
 *  niveau 6+) ? */
function hasAlcoolemie(character) {
  return (character.classes || []).some((c) => c.classId === "mercenaire" && c.subclass === "Groupe des Trois Futs" && c.level >= 6);
}

function CharacterTabs({ character, race, onChange }) {
  const [tab, setTab] = useState("Aperçu");
  const [xpShopOpen, setXpShopOpen] = useState(false);
  const layers = computeStatLayers(character, race);
  const classes = character.classes || [];
  const totalLevel = classes.reduce((s, c) => s + c.level, 0);
  const origin = race && character.originIndex !== null ? race.origins[character.originIndex] : null;
  const isMage = classes.some((c) => {
    const cls = CLASSES.find((x) => x.id === c.classId);
    return classGrantsMagic(cls);
  }) || !!raceMagicDomain(race, character.originIndex, character);
  const isMercenaireAlcool = hasAlcoolemie(character);
  const classSummary = classes.map((c) => {
    const cls = CLASSES.find((x) => x.id === c.classId);
    return `${cls?.name || "?"} ${c.level}${c.subclass ? ` (${c.subclass})` : ""}`;
  }).join(" / ");

  // Synchronise automatiquement les compétences "Art de la magie" ET les sorts accordés par la
  // race (choisi ou automatique) et/ou les classes qui donnent accès à la magie. La sélection au
  // clic (selectRaceSpell, toggleFreeSpell) reste immédiate ; cet effet réconcilie en plus les cas
  // indirects (changement de race en cours d'édition, domaine devenu invalide, classe Templaris
  // devenue incompatible avec la race, etc.).
  useEffect(() => {
    const { skills: wantedSkills, spells: wantedSpells } = computeMagicSkillGrants(character, race);
    const skillsPassive = character.skillsPassive || [];
    const spells = character.spells || [];
    const isGrantTag = (tag) => tag === "race" || tag === "merged" || tag === "race-auto" || (typeof tag === "string" && tag.startsWith("class:"));
    const patch = {};

    const currentGrantedSkills = skillsPassive.filter((s) => isGrantTag(s.grantedBy));
    const skillsMatch = currentGrantedSkills.length === wantedSkills.length &&
      currentGrantedSkills.every((s) => wantedSkills.some((w) => w.grantedBy === s.grantedBy && w.domain === s.domain && w.niveau === s.niveau));
    if (!skillsMatch) {
      const kept = skillsPassive.filter((s) => !isGrantTag(s.grantedBy));
      patch.skillsPassive = [...kept, ...wantedSkills.map((w) => ({ id: "c" + Math.random().toString(36).slice(2, 9), ...w }))];
    }

    const currentGrantedSpells = spells.filter((s) => isGrantTag(s.grantedBy));
    const spellsMatch = currentGrantedSpells.length === wantedSpells.length &&
      currentGrantedSpells.every((s) => wantedSpells.some((w) => w.grantedBy === s.grantedBy && w.nom === s.nom));
    if (!spellsMatch) {
      const kept = spells.filter((s) => !isGrantTag(s.grantedBy));
      patch.spells = [...kept, ...wantedSpells.map((w) => ({ id: "s" + Math.random().toString(36).slice(2, 9), ...w }))];
    }

    // Retire une éventuelle classe Templaris devenue incompatible avec la race (Draconoïde/Demi-Astralis).
    const classes = character.classes || [];
    if (race && isClassBlockedForRace("templaris", race) && classes.some((c) => c.classId === "templaris")) {
      patch.classes = classes.filter((c) => c.classId !== "templaris");
    }

    // Elfes Blancs : ajoute automatiquement la Bourse de terre de l'Île Blanche à l'inventaire
    // (trait "Mal du pays"), avec un interrupteur "Possédée" géré dans l'onglet Inventaire.
    const inventory = character.inventory || [];
    const hasBourse = inventory.some((it) => it.isBourseTerre);
    if (race && race.id === "elfes-blancs" && !hasBourse) {
      patch.inventory = [...inventory, {
        id: "i" + Math.random().toString(36).slice(2, 9), nom: "Bourse de terre de l'Île Blanche",
        poids: "0.1 kg", prix: "—", type: "Objet rituel", category: "autre", isBourseTerre: true,
        description: "Trait « Mal du pays ». En cas de perte : malus de 25% à toutes vos statistiques.",
        equipped: true, note: "",
      }];
    } else if ((!race || race.id !== "elfes-blancs") && hasBourse) {
      patch.inventory = inventory.filter((it) => !it.isBourseTerre);
    }

    if (Object.keys(patch).length > 0) onChange(patch);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [race?.id, character.originIndex, character.savoirAmbivalentChoice, character.savoirAmbivalentDomain, JSON.stringify((character.classes || []).map((c) => ({ id: c.classId, d: c.magicDomain })))]);

  return (
    <div className="sheet">
      <div className="sheet-header">
        <div className="sheet-header-left">
          {character.photo && (
            <img src={character.photo} alt="" className="sheet-avatar" />
          )}
          <div>
            <div className="sheet-name">{character.name || "Sans nom"}</div>
            <div className="sheet-tag">{race?.name || "—"}{origin ? ` · ${origin.name}` : ""} — {classSummary || "Aucune classe"}</div>
          </div>
        </div>
        <div className="rank-badge">
          <div className="rank-badge-num">{totalLevel}</div>
          <div className="rank-badge-label">Niveau total</div>
        </div>
      </div>

      {xpShopOpen ? (
        <XpShopPage character={character} race={race} onChange={onChange} onBack={() => setXpShopOpen(false)} />
      ) : (
        <>
          <div className="sheet-tabbar">
            {SHEET_TABS.map((t) => (
              (t !== "Sorts" || isMage) && (t !== "Alcoolémie" || isMercenaireAlcool) && (
                <button key={t} className={"sheet-tab" + (tab === t ? " active" : "")} onClick={() => setTab(t)}>{t}</button>
              )
            ))}
          </div>

          {tab === "Aperçu" && (
            <TabApercu character={character} race={race} layers={layers} totalLevel={totalLevel} origin={origin} onChange={onChange} onOpenXpShop={() => setXpShopOpen(true)} />
          )}
          {tab === "Compétences" && <TabActions character={character} race={race} onChange={onChange} layers={layers} originIndex={character.originIndex} />}
          {tab === "Sorts" && isMage && <TabSpells character={character} onChange={onChange} />}
          {tab === "Alcoolémie" && isMercenaireAlcool && <TabAlcoolemie character={character} onChange={onChange} />}
          {tab === "Inventaire" && <TabInventory character={character} onChange={onChange} />}
          {tab === "Notes" && <TabNotes character={character} onChange={onChange} />}
        </>
      )}
    </div>
  );
}

/* --- Onglet Aperçu : hexaèdre, PV/armure, destin, réputation, armes --- */

function TabApercu({ character, race, layers, totalLevel, origin, onChange, onOpenXpShop }) {
  const effectiveStats = {};
  STATS.forEach((s) => (effectiveStats[s.key] = layers[s.key].effective));
  const hasTempBonus = STATS.some((s) => layers[s.key].tempBonus !== 0);
  const pvClassBonus = computeClassPvBonus(character);
  const classInitBonus = computeClassInitiativeBonus(character);
  const pvMax = layers.CON.permanent + pvClassBonus.total;
  const pvCurrent = clamp(pvMax - (character.pvDamage || 0), -Math.round(pvMax * 0.75) - 5, pvMax);
  const destinMax = race ? race.destinPoints : 3;
  const armor = character.armor || { physique: 0, magique: 0, temporaire: 0, degatPermanent: 0 };
  const equippedArmor = computeEquippedArmor(character);
  const weapons = character.weapons && character.weapons.length ? character.weapons : [emptyWeapon(), emptyWeapon(), emptyWeapon()];
  const speedCategory = effectiveSpeedCategory(character, race);
  const speedInfo = SPEED_CATEGORIES[speedCategory];
  const isMecanotrix = race && race.id === "mecanotrix";
  const regenPerNight = isMecanotrix ? 0 : Math.floor(pvMax / 10);
  const elanInfo = getElanArtistiqueInfo(character);

  function setTempBonus(key, value) {
    onChange({ tempBonuses: { ...(character.tempBonuses || emptyBonuses()), [key]: value } });
  }
  function resetTempBonuses() { onChange({ tempBonuses: emptyBonuses() }); }
  function setPvDamage(v) { onChange({ pvDamage: clamp(v, 0, pvMax + Math.round(pvMax * 0.75) + 5) }); }
  function takeRest() {
    const toggles = { ...(character.activeToggles || {}) };
    let hadFatigue = false;
    Object.keys(toggles).forEach((k) => { if (k.endsWith(":fatigue") && toggles[k]) { toggles[k] = false; hadFatigue = true; } });
    const patch = { pvDamage: Math.max(0, (character.pvDamage || 0) - regenPerNight), dailyUses: {}, activeToggles: toggles };
    if (hadFatigue) patch.tempBonuses = emptyBonuses();
    onChange(patch);
  }
  function setArmor(key, v) { onChange({ armor: { ...armor, [key]: v } }); }
  function setDestinUsed(v) { onChange({ destinUsed: clamp(v, 0, destinMax) }); }
  function setWeapon(i, key, v) {
    const next = weapons.map((w, idx) => (idx === i ? { ...w, [key]: v } : w));
    onChange({ weapons: next });
  }

  return (
    <div className="tab-panel">
      <div className="sheet-grid">
        <div className="sheet-panel">
          <h3><RuleTerm term="hexaedre">Hexaèdre</RuleTerm></h3>
          <HexRadar stats={character.stats} effectiveStats={effectiveStats} size={230}
            onDragEffective={(key, value) => setTempBonus(key, value - layers[key].permanent)} />
          <div className="legend-row">
            <span><i className="dot teal" /> Stat pure</span>
            <span><i className="dot gold" /> Stat effective (permanent + temporaire)</span>
          </div>

          <div className="stat-breakdown">
            <div className="stat-breakdown-head">
              <span>Stat</span><span>Pure</span><span>Perm.</span><span>Temp.</span><span>Effective</span><span><RuleTerm term="critique">Crit.</RuleTerm></span>
            </div>
            {STATS.map((s) => {
              const l = layers[s.key];
              return (
                <div key={s.key} className="stat-breakdown-row">
                  <span className="sb-name">{s.name}</span>
                  <span>{l.pure}%</span>
                  <span className={l.permBonus ? "sb-up" : ""}>
                    {l.permanent}%
                    {l.permBonus !== 0 && l.permSources.length > 0 && (
                      <InfoHover label="ⓘ">
                        <strong>Origine du bonus permanent</strong>
                        {l.permSources.map((src, i) => (
                          <span key={i}>{src.from} — {src.name} : {src.amount >= 0 ? "+" : ""}{src.amount}%</span>
                        ))}
                      </InfoHover>
                    )}
                  </span>
                  <span>
                    <input
                      type="number" className="temp-input" value={l.tempBonus}
                      onChange={(e) => setTempBonus(s.key, parseInt(e.target.value || "0", 10))}
                    />
                  </span>
                  <span className="sb-effective">
                    {l.effective}%
                    <RollCopyButton formula="/roll 1d100" title={`Copier le jet pour ${s.name} (réussite si ≤ ${l.effective}%)`} />
                  </span>
                  <span>
                    {l.critBonus > 0 && <span className="sb-crit-up" title="Ajouté à la plage de réussite critique (base 5%)">+{l.critBonus}% RC</span>}
                    {l.critFailBonus > 0 && <span className="sb-crit-down" title="Ajouté à la plage d'échec critique (base 5%)">+{l.critFailBonus}% EC</span>}
                  </span>
                </div>
              );
            })}
          </div>
          <div className="temp-actions">
            <p className="hint small">Bonus/malus temporaires (sorts, blessures, effets de combat…). Une statistique est plafonnée à 95% (et ne descend jamais sous 5%) : le surplus se convertit en bonus de réussite critique (RC), le déficit en bonus d'échec critique (EC), tous deux ajoutés à la base de 5%.</p>
            {hasTempBonus && <button className="btn ghost small" onClick={resetTempBonuses}>Réinitialiser les bonus temporaires</button>}
          </div>
        </div>

        <div className="sheet-panel">
          <h3><RuleTerm term="xp">Niveau &amp; expérience</RuleTerm></h3>
          <div className="xp-row">
            <div className="level-badge-big">{totalLevel}</div>
            <div className="level-xp-col">
              <p className="hint small" style={{ margin: 0 }}>Niveau total (somme des niveaux de toutes les classes).</p>
            </div>
          </div>

          {(() => {
            const spent = totalSpentXp(character);
            const total = character.xp || 0;
            const available = total - spent;
            const pct = total > 0 ? Math.min(100, (spent / total) * 100) : 0;
            return (
              <div className="xp-bar-block">
                <div className="xp-bar-track">
                  <div className="xp-bar-fill" style={{ width: `${pct}%` }} />
                </div>
                <p className="hint small" style={{ margin: "4px 0 0" }}>
                  {spent} dépensée / {total} XP totale — <strong className={available < 0 ? "sb-down" : ""}>{available} disponible</strong>
                </p>
              </div>
            );
          })()}

          <div className="xp-edit-row">
            <label>XP totale (maximum cumulé, gagné en jeu)
              <input type="number" min="0" value={character.xp || 0}
                onChange={(e) => onChange({ xp: Math.max(0, parseInt(e.target.value || "0", 10)) })} />
            </label>
            <button className="btn ghost small" onClick={() => onChange({ xp: (character.xp || 0) + 100 })}>+100 XP</button>
            <button className="btn primary small" onClick={onOpenXpShop}>Dépenser de l'XP →</button>
          </div>

          <h3>Valeurs dérivées</h3>
          <div className="derived-grid">
            <Derived label="Chance" value="50" roll="/roll 1d100" rollTitle="Copier le jet de Chance (réussite si ≤ 50%)" />
            <Derived
              label={<>
                <RuleTerm term="initiative">Initiative</RuleTerm>
                {classInitBonus.total > 0 && (
                  <InfoHover label="ⓘ">
                    <strong>Origine du bonus d'Initiative (+{classInitBonus.total})</strong>
                    {classInitBonus.sources.map((src, i) => <span key={i}>{src.className} — {src.name} : +{src.amount}</span>)}
                  </InfoHover>
                )}
              </>}
              value={`1d100 + ${layers.AGI.effective + classInitBonus.total}${speedInfo.initiativeMod ? (speedInfo.initiativeMod > 0 ? ` +${speedInfo.initiativeMod}` : ` ${speedInfo.initiativeMod}`) : ""}`}
              roll={`/roll 1d100+${layers.AGI.effective + classInitBonus.total + speedInfo.initiativeMod}`} rollTitle="Copier le jet d'Initiative" />
            <Derived label="Régén. / nuit" value={isMecanotrix ? "0 (aucune)" : regenPerNight} />
          </div>

          <h3>Vitesse</h3>
          <div className="rep-row">
            <label>Catégorie
              <select value={speedCategory} onChange={(e) => onChange({ speedCategory: e.target.value })}>
                {Object.keys(SPEED_CATEGORIES).map((cat) => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </label>
            <Derived label="Portée de déplacement" value={`${speedInfo.range}m`} />
          </div>

          {elanInfo.unlocked && (
            <>
              <h3>Élan artistique</h3>
              <p className="hint small" style={{ margin: "0 0 6px" }}>
                Gagner : action complexe (test de CHA artistique) ou succès critique en CHA. Utiliser (sur vous, un allié ou un ennemi) : +10% à une action, +4 dégâts, ou +4 armure — au choix, en bonus ou en malus.
              </p>
              <div className="ivresse-pi">
                <button className="btn ghost small" onClick={() => onChange({ elanArtistique: clamp((character.elanArtistique || 0) - 1, 0, elanInfo.max) })}>− Ea</button>
                <span className="ivresse-pi-value">{character.elanArtistique || 0} / {elanInfo.max}</span>
                <button className="btn ghost small" onClick={() => onChange({ elanArtistique: clamp((character.elanArtistique || 0) + 1, 0, elanInfo.max) })}>+ Ea</button>
              </div>
            </>
          )}

          {(() => {
            const artMagie = (character.skillsPassive || []).find((s) => s.nom === "Art de la magie" && s.niveau);
            if (!artMagie) return null;
            return (
              <>
                <h3>Art de la magie{artMagie.domain ? ` — ${artMagie.domain}` : ""}</h3>
                <SpellCastHelper level={parseInt(artMagie.niveau, 10) || 1} />
              </>
            );
          })()}

          <h3><RuleTerm term="pv">Points de vie</RuleTerm></h3>
          <div className="pv-row">
            <button className="btn ghost small" onClick={() => setPvDamage((character.pvDamage || 0) + 1)}>− PV</button>
            <div className="pv-display">
              <strong>{pvCurrent}</strong> / {pvMax}
              {pvClassBonus.total > 0 && (
                <InfoHover label="ⓘ">
                  <strong>Origine du bonus de PV max (+{pvClassBonus.total})</strong>
                  {pvClassBonus.sources.map((src, i) => (
                    <span key={i}>{src.className} — {src.name} : +{src.amount}</span>
                  ))}
                </InfoHover>
              )}
            </div>
            <button className="btn ghost small" onClick={() => setPvDamage(Math.max(0, (character.pvDamage || 0) - 1))}>+ PV</button>
            <button className="btn primary small" onClick={takeRest} title="Régénère les PV naturellement (régén./nuit), réinitialise les usages par jour et lève la fatigue">💤 Repos</button>
          </div>

          <h3><RuleTerm term="armure">Armure</RuleTerm></h3>
          <img src={LOGO_ARMURE} alt="" className="armor-logo" />
          <div className="armor-row">
            {["physique", "magique", "temporaire", "degatPermanent"].map((k) => {
              const raceBonus = k === "physique" && race && race.traits.some((t) => t.name === "Corps métallique") ? 3 : 0;
              const equipBonus = (k === "physique" || k === "magique") ? equippedArmor[k] : 0;
              const labels = { physique: "Physique", magique: "Magique", temporaire: "Temporaire", degatPermanent: "Dégât permanent" };
              const editable = k === "temporaire" || k === "degatPermanent";
              return (
                <label key={k} className="armor-field">
                  {labels[k]}
                  {editable ? (
                    <input type="number" value={armor[k] || 0} placeholder={k === "degatPermanent" ? "-3" : "0"}
                      onChange={(e) => setArmor(k, parseInt(e.target.value || "0", 10))} />
                  ) : (
                    <span className="armor-readonly">{equipBonus + raceBonus}</span>
                  )}
                  {(raceBonus > 0 || equipBonus > 0) && (
                    <span className="armor-race-bonus">
                      <InfoHover label="ⓘ Détail">
                        <strong>Origine du bonus</strong>
                        {raceBonus > 0 && <span>Corps métallique (Mécanotrix) : +{raceBonus}</span>}
                        {equipBonus > 0 && <span>Équipement (armure/bouclier équipés) : +{equipBonus}</span>}
                      </InfoHover>
                    </span>
                  )}
                </label>
              );
            })}
          </div>

          <h3><RuleTerm term="destin">Points de destin</RuleTerm></h3>
          <div className="destin-row">
            <button className="btn ghost small" onClick={() => setDestinUsed((character.destinUsed || 0) + 1)}>Dépenser</button>
            <div className="destin-pips">
              {Array.from({ length: destinMax }).map((_, i) => (
                <span key={i} className={"destin-pip" + (i < (destinMax - (character.destinUsed || 0)) ? " full" : "")} />
              ))}
            </div>
            <button className="btn ghost small" onClick={() => setDestinUsed((character.destinUsed || 0) - 1)}>Restaurer</button>
            <span className="hint small" style={{ margin: 0 }}>{destinMax - (character.destinUsed || 0)} / {destinMax}</span>
          </div>

          <h3><RuleTerm term="reputation">Réputation</RuleTerm> &amp; <RuleTerm term="corruption">corruption</RuleTerm></h3>
          <div className="rep-row">
            <label>Réputation (-10 à +10)
              <input type="number" min="-10" max="10" value={character.reputation || 0}
                onChange={(e) => onChange({ reputation: clamp(parseInt(e.target.value || "0", 10), -10, 10) })} />
            </label>
            <label>Corruption démoniaque
              <input type="number" min="0" value={character.corruption || 0}
                onChange={(e) => onChange({ corruption: Math.max(0, parseInt(e.target.value || "0", 10)) })} />
            </label>
          </div>
        </div>
      </div>

      <div className="sheet-panel wide">
        <h3>Armes</h3>
        <div className="weapons-table with-stat">
          <div className="weapons-table-head">
            <span>Nom</span><span>Type</span><span>Stat</span><span>Dégâts</span><span>Bonus dégâts</span><span>Bonus</span><span>Particularité</span><span />
          </div>
          {(() => {
            const dmgBonuses = computeWeaponDamageBonuses(character, race);
            const hoverContent = (
              <InfoHover label="ⓘ">
                <strong>Bonus de dégâts disponibles</strong>
                {dmgBonuses.sources.map((b, i) => (
                  <span key={i}>{b.label} : +{b.amount} ({b.note}){!b.active && " — inactif"}</span>
                ))}
                <span><strong>Total actif actuellement : {dmgBonuses.total >= 0 ? "+" : ""}{dmgBonuses.total}</strong></span>
              </InfoHover>
            );
            return (
              <>
                {weapons.map((w, i) => (
                  <div className="weapons-table-row" key={i}>
                    <input value={w.nom || ""} placeholder={`Arme ${i + 1}`} onChange={(e) => setWeapon(i, "nom", e.target.value)} />
                    <span className="weapon-readonly">{w.type || "—"}</span>
                    <span className="weapon-readonly">{extractWeaponStat(w.type) || "—"}</span>
                    <input value={w.degats} placeholder="Dégâts" onChange={(e) => setWeapon(i, "degats", e.target.value)} />
                    <span className="weapon-bonus-degats-cell">
                      <input value={w.bonusDegats} placeholder="+0" onChange={(e) => setWeapon(i, "bonusDegats", e.target.value)} />
                      <button className="icon-btn" title="Actualiser avec le total calculé" onClick={() => setWeapon(i, "bonusDegats", String(dmgBonuses.total))}>↻</button>
                      {dmgBonuses.sources.length > 0 && hoverContent}
                    </span>
                    <input value={w.bonus} placeholder="Bonus" onChange={(e) => setWeapon(i, "bonus", e.target.value)} />
                    <input value={w.particularite} placeholder="Particularité" onChange={(e) => setWeapon(i, "particularite", e.target.value)} />
                    <button className="icon-btn" title="Retirer cette arme" onClick={() => onChange({ weapons: weapons.map((ww, j) => (j === i ? emptyWeapon() : ww)) })}>✕</button>
                  </div>
                ))}
                <div className="weapons-table-row">
                  <span className="weapon-readonly">Poing</span>
                  <span className="weapon-readonly">1 main, FOR</span>
                  <span className="weapon-readonly">FOR</span>
                  <span className="weapon-readonly">1d6</span>
                  <span className="weapon-bonus-degats-cell">
                    <span className="weapon-readonly">{dmgBonuses.total >= 0 ? "+" : ""}{dmgBonuses.total}</span>
                    {dmgBonuses.sources.length > 0 && hoverContent}
                  </span>
                  <span className="weapon-readonly">+0</span>
                  <span className="weapon-readonly">Aucune</span>
                  <span />
                </div>
              </>
            );
          })()}
        </div>
      </div>

      <SpellSummaryPanel character={character} />

      <ThematicBonusTracker character={character} onChange={onChange} />
    </div>
  );
}

/** Détecte une formule de DÉGÂTS (pas une simple durée en tours) dans le texte d'un sort,
 *  en cherchant un motif "infligez/inflige X" ou "X de dégâts" autour du jet de dés. */
function detectDamageFormula(text) {
  if (!text) return null;
  let m = text.match(/inflige[a-zàâäéèêëïîôöùûüç]*\s+(\d+d\d+(?:\s*\+\s*\d+)?)/i);
  if (m) return m[1].replace(/\s+/g, "");
  m = text.match(/(\d+d\d+(?:\s*\+\s*\d+)?)\s*(?:de\s+)?d[ée]g[âa]ts?/i);
  if (m) return m[1].replace(/\s+/g, "");
  return null;
}

/** Retrouve le domaine d'un sort à partir de son nom (recherche inverse dans le compendium). */
function findSpellDomain(name) {
  for (const d of MAGIC_DOMAINS_DATA) {
    if (d.spells.some((s) => s.nom === name)) return d.name;
  }
  return null;
}

function extractRangeBonus(text) {
  if (!text || !/sorts?/i.test(text) || /d[ée]placement/i.test(text)) return null;
  const m = text.match(/\+(\d+)\s*m\s*(?:de\s+)?port[ée]e/i);
  return m ? parseInt(m[1], 10) : null;
}
function extractSpellDamageBonus(text) {
  if (!text || !/sorts?/i.test(text)) return null;
  const m = text.match(/\+(\d+)\s*d[ée]g[âa]ts?/i);
  return m ? parseInt(m[1], 10) : null;
}
/** Rassemble, pour toutes les classes possédées, les bonus de portée/dégâts de sorts détectés
 *  dans les niveaux débloqués (texte libre) — appliqués directement aux colonnes des tableaux
 *  de sorts (pas seulement un rappel). La Posture de Rosace (Mage de Guerre) est gérée à part
 *  (système de choix dédié) et donc exclue ici pour éviter un double-comptage. */
function computeSpellLevelBonuses(character) {
  const classes = character.classes || [];
  const range = [];
  const damage = [];
  classes.forEach((entry) => {
    const actions = buildActionList(entry.classId, entry.subclass, entry.level);
    actions.forEach((a) => {
      if (/rosace|flux (brutal|stable|conduit)/i.test(a.name)) return;
      const r = extractRangeBonus(a.desc);
      if (r) range.push({ name: a.name, amount: r });
      const dmg = extractSpellDamageBonus(a.desc);
      if (dmg) damage.push({ name: a.name, amount: dmg, desc: a.desc });
    });
  });
  const posture = getRosacePostureInfo(character);
  if (posture.active === "brutal" && posture.tier) {
    damage.push({ name: `Posture de Rosace — ${posture.tier.label}`, amount: posture.tier.degats, desc: posture.tier.note });
  }
  return { range, damage };
}

/** Paliers de la posture "Flux Brutal" (Mage de Guerre), du plus élevé débloqué au plus bas. */
const FLUX_BRUTAL_TIERS = [
  { requires: "Cœur de Rosace", label: "Cœur de Rosace", degats: 9, dice: 1 },
  { requires: "Flux Brutal supérieur II", label: "Flux Brutal supérieur II", degats: 9, dice: 3 },
  { requires: "Flux Brutal supérieur I", label: "Flux Brutal supérieur I", degats: 6, dice: 2 },
  { requires: "Posture de Rosace", label: "Flux Brutal (base)", degats: 3, dice: 1 },
];
/** Calcule la posture de Rosace active du personnage (Mage de Guerre) et le palier actuel de
 *  Flux Brutal débloqué (le plus avancé parmi les niveaux déjà atteints). */
function getRosacePostureInfo(character) {
  const classes = character.classes || [];
  const mdgEntry = classes.find((c) => c.classId === "mage" && c.subclass === "Mage de Guerre");
  if (!mdgEntry) return { unlocked: false, active: null, tier: null };
  const actionNames = new Set(buildActionList("mage", "Mage de Guerre", mdgEntry.level).map((a) => a.name));
  if (!actionNames.has("Posture de Rosace")) return { unlocked: false, active: null, tier: null };
  const tier = FLUX_BRUTAL_TIERS.find((t) => actionNames.has(t.requires)) || null;
  const stableAmeliore = actionNames.has("Flux Stable amélioré");
  const conduitTier = actionNames.has("Flux Conduit supérieur") ? "supérieur (relance 1 ou 2)"
    : actionNames.has("Flux Conduit amélioré") ? "amélioré (2×/jour)" : "de base (1×/jour)";
  return {
    unlocked: true,
    active: character.rosacePosture || null,
    tier: tier ? { ...tier, note: `+${tier.degats} dégâts aux sorts, +${tier.dice}d10 supplémentaire(s) pour le phénomène magique.` } : null,
    stableNote: stableAmeliore
      ? "Ignore un 9 sans perdre le dé associé au lancement du sort."
      : "Ignore le premier 9 par lancement de sort (le dé n'est pas utilisé pour le lancement).",
    conduitNote: `Ajouter +1d10 à un jet de sort après avoir vu le résultat — ${conduitTier}.`,
  };
}

/** Paliers de stockage maximal des Élans artistiques (Délivreur). */
const ELAN_MAX_TIERS = [
  { requires: "Elan attendu III", max: 8 },
  { requires: "Elan attendu II", max: 6 },
  { requires: "Elan attendu I", max: 4 },
  { requires: "Élan artistique", max: 3 },
];
/** Le personnage a-t-il débloqué les Élans artistiques (Délivreur, niveau 3+) et quel est son
 *  stockage maximal actuel ? */
function getElanArtistiqueInfo(character) {
  const classes = character.classes || [];
  const delEntry = classes.find((c) => c.classId === "delivreur");
  if (!delEntry) return { unlocked: false, max: 0 };
  const actionNames = new Set(buildActionList("delivreur", delEntry.subclass, delEntry.level).map((a) => a.name));
  if (!actionNames.has("Élan artistique")) return { unlocked: false, max: 0 };
  const tier = ELAN_MAX_TIERS.find((t) => actionNames.has(t.requires));
  return { unlocked: true, max: tier ? tier.max : 3 };
}

/** Interprète le champ "portée" libre d'un sort : valeur numérique en m, ou libellé spécial
 *  (Contact, Utilisateur…) quand il n'y a pas de distance à proprement parler. */
function parsePortee(porteeStr) {
  if (!porteeStr) return { numeric: null, label: "—" };
  const m = String(porteeStr).match(/^(\d+)\s*m/i);
  if (m) return { numeric: parseInt(m[1], 10), label: `${m[1]}m` };
  if (/utilisateur/i.test(porteeStr)) return { numeric: null, label: "Utilisateur" };
  if (/contact/i.test(porteeStr)) return { numeric: null, label: "Contact" };
  return { numeric: null, label: String(porteeStr) };
}

function detectProjectiles(text) {
  if (!text) return null;
  const m = text.match(/(\d+)\s*projectiles?/i);
  return m ? parseInt(m[1], 10) : null;
}

/** Enrichit chaque sort connu (appris, gratuits de classe, accordés par la race) avec les bonus
 *  de dégâts/portée détectés dans les niveaux de classe débloqués, et classe le sort en
 *  "offensif" (formule de dégâts détectée) ou "soutien". */
function enrichSpells(character) {
  const allSpells = [
    ...(character.spells || []),
    ...((character.classes || []).flatMap((c) => c.freeSpells || [])),
  ];
  const { range: rangeList, damage: damageList } = computeSpellLevelBonuses(character);
  const totalRangeBonus = rangeList.reduce((s, b) => s + b.amount, 0);
  const totalDamageBonus = damageList.reduce((s, b) => s + b.amount, 0);
  const mdgLevel = mageDeGuerreLevel(character);

  return allSpells.map((sp) => {
    const dmgFormula = detectDamageFormula(sp.effets);
    const isOffensive = !!dmgFormula;
    const porteeInfo = parsePortee(sp.portee);
    const isSignature = mdgLevel >= 14 && character.signatureSpellName === sp.nom;
    return {
      ...sp,
      isOffensive,
      isSignature,
      dmgFormula,
      dmgBonus: isOffensive ? totalDamageBonus : 0,
      dmgBonusSources: isOffensive ? damageList : [],
      porteeLabel: porteeInfo.label,
      porteeNumeric: porteeInfo.numeric,
      porteeBonus: (porteeInfo.numeric !== null ? totalRangeBonus : 0) + (isSignature && mdgLevel >= 23 ? 5 : 0),
      porteeBonusSources: porteeInfo.numeric !== null ? rangeList : [],
      projectiles: detectProjectiles(sp.effets),
    };
  });
}

/** Les deux tableaux de sorts (Offensifs / Soutiens), réutilisés dans l'Aperçu (sans description)
 *  et dans l'onglet Sorts (avec description). Les bonus de dégâts/portée détectés dans les
 *  niveaux de classe sont directement intégrés dans leurs colonnes dédiées. */
function SpellTables({ character, showDesc }) {
  const enriched = enrichSpells(character);
  if (enriched.length === 0) return null;
  const offensive = enriched.filter((sp) => sp.isOffensive);
  const support = enriched.filter((sp) => !sp.isOffensive);
  const hasProjectiles = offensive.some((sp) => sp.projectiles);

  return (
    <>
      {offensive.length > 0 && (
        <div className="spell-summary-block">
          <h4 className="action-subheading">Sorts offensifs</h4>
          <div className={"spell-table" + (hasProjectiles ? " with-proj" : "")}>
            <div className="spell-table-row spell-table-head">
              <span>Nom</span><span>Dégâts</span><span>Dégât bonus</span><span>Portée</span><span>Portée bonus</span>
              {hasProjectiles && <span>Projectiles</span>}
            </div>
            {offensive.map((sp, i) => (
              <div className="spell-table-row" key={sp.id || i}>
                <span className="spell-table-name">
                  {sp.nom}{sp.isSignature && <span className="improved-tag" style={{ marginLeft: 6 }}>Signature</span>}
                  {showDesc && sp.effets && <span className="spell-table-desc">{sp.effets}</span>}
                </span>
                <span>{sp.dmgFormula}{sp.dmgFormula && <RollCopyButton formula={`/roll ${sp.dmgFormula}`} title={`Copier le jet de dégâts pour ${sp.nom}`} />}</span>
                <span>
                  {sp.dmgBonus ? `+${sp.dmgBonus}` : "—"}
                  {sp.dmgBonus > 0 && (
                    <InfoHover label="ⓘ">
                      <strong>Origine du bonus de dégâts</strong>
                      {sp.dmgBonusSources.map((b, j) => <span key={j}>{b.name} : +{b.amount} — {b.desc}</span>)}
                    </InfoHover>
                  )}
                </span>
                <span>{sp.porteeLabel}</span>
                <span>
                  {sp.porteeBonus ? `+${sp.porteeBonus}m` : "—"}
                  {sp.porteeBonus > 0 && (
                    <InfoHover label="ⓘ">
                      <strong>Origine du bonus de portée</strong>
                      {sp.porteeBonusSources.map((b, j) => <span key={j}>{b.name} : +{b.amount}m</span>)}
                    </InfoHover>
                  )}
                </span>
                {hasProjectiles && <span>{sp.projectiles || "—"}</span>}
              </div>
            ))}
          </div>
        </div>
      )}
      {support.length > 0 && (
        <div className="spell-summary-block">
          <h4 className="action-subheading">Sorts soutiens</h4>
          <div className="spell-table support">
            <div className="spell-table-row spell-table-head support">
              <span>Nom</span><span>Portée</span><span>Portée bonus</span>
            </div>
            {support.map((sp, i) => (
              <div className="spell-table-row support" key={sp.id || i}>
                <span className="spell-table-name">
                  {sp.nom}{sp.isSignature && <span className="improved-tag" style={{ marginLeft: 6 }}>Signature</span>}
                  {showDesc && sp.effets && <span className="spell-table-desc">{sp.effets}</span>}
                </span>
                <span>{sp.porteeLabel}</span>
                <span>{sp.porteeBonus ? `+${sp.porteeBonus}m` : "—"}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </>
  );
}

function SpellSummaryPanel({ character }) {
  const allSpells = [
    ...(character.spells || []),
    ...((character.classes || []).flatMap((c) => c.freeSpells || [])),
  ];
  if (allSpells.length === 0) return null;

  const domainsKnown = [...new Set(allSpells.map((sp) => findSpellDomain(sp.nom)).filter(Boolean))];
  const seuilBonuses = (character.thematicBonuses || []).filter((b) => /seuil/i.test(b.tag));

  function bonusesForDomain(domain) {
    const shortName = domain.replace(/^Magie\s+/i, "").toLowerCase();
    return seuilBonuses.filter((b) => b.tag.toLowerCase().includes(shortName));
  }
  const generalBonuses = domainsKnown.length > 1
    ? seuilBonuses.filter((b) => !domainsKnown.some((d) => bonusesForDomain(d).includes(b)))
    : seuilBonuses;

  return (
    <div className="sheet-panel wide">
      <h3>Sorts</h3>
      {seuilBonuses.length > 0 && (
        <div className="spell-summary-block">
          <h4 className="action-subheading">Réductions de seuil disponibles</h4>
          {domainsKnown.length > 1 ? (
            <>
              {domainsKnown.map((d) => {
                const list = bonusesForDomain(d);
                if (list.length === 0) return null;
                const total = list.reduce((s, b) => s + Number(b.amount || 0), 0);
                return (
                  <p key={d} className="hint small" style={{ margin: "2px 0" }}>
                    <strong>{d}</strong> : -{total} ({list.map((b) => `${b.tag} : -${b.amount}`).join(", ")})
                  </p>
                );
              })}
              {generalBonuses.length > 0 && (
                <p className="hint small" style={{ margin: "2px 0" }}>
                  <strong>Général</strong> : -{generalBonuses.reduce((s, b) => s + Number(b.amount || 0), 0)} ({generalBonuses.map((b) => `${b.tag} : -${b.amount}`).join(", ")})
                </p>
              )}
            </>
          ) : (
            <p className="hint small" style={{ margin: "2px 0" }}>
              Total : -{seuilBonuses.reduce((s, b) => s + Number(b.amount || 0), 0)} ({seuilBonuses.map((b) => `${b.tag} : -${b.amount}`).join(", ")})
            </p>
          )}
        </div>
      )}
      <SpellTables character={character} showDesc={false} />
    </div>
  );
}

/**
 * Suivi des bonus thématiques (ex. "+20 en milieu naturel", "+15% PER en phase de repos").
 * Ces bonus viennent de descriptions libres de techniques/traits qu'on ne peut pas extraire
 * automatiquement du texte — le joueur les ajoute au fur et à mesure qu'il les repère dans ses
 * actions. Les entrées partageant le même tag se cumulent automatiquement.
 */
function ThematicBonusTracker({ character, onChange }) {
  const list = character.thematicBonuses || [];
  const [tag, setTag] = useState("");
  const [amount, setAmount] = useState(0);
  const [stat, setStat] = useState("");
  const [note, setNote] = useState("");
  const toggles = character.activeToggles || {};

  function add() {
    if (!tag.trim()) return;
    onChange({ thematicBonuses: [...list, { id: "tb" + Math.random().toString(36).slice(2, 9), tag: tag.trim(), amount, stat: stat || null, note }] });
    setTag(""); setAmount(0); setStat(""); setNote("");
  }
  function remove(entry) {
    const key = "tb:" + entry.id;
    let patch = { thematicBonuses: list.filter((b) => b.id !== entry.id) };
    if (entry.stat && toggles[key]) {
      const temp = { ...(character.tempBonuses || emptyBonuses()) };
      temp[entry.stat] = (temp[entry.stat] || 0) - Number(entry.amount || 0);
      patch = { ...patch, tempBonuses: temp, activeToggles: { ...toggles, [key]: false } };
    }
    onChange(patch);
  }
  function toggleStatBonus(entry) {
    if (!entry.stat) return;
    const key = "tb:" + entry.id;
    const isOn = !!toggles[key];
    const temp = { ...(character.tempBonuses || emptyBonuses()) };
    temp[entry.stat] = (temp[entry.stat] || 0) + (isOn ? -Number(entry.amount || 0) : Number(entry.amount || 0));
    onChange({ tempBonuses: temp, activeToggles: { ...toggles, [key]: !isOn } });
  }

  const groups = {};
  list.forEach((b) => {
    const key = b.tag.trim().toLowerCase();
    if (!groups[key]) groups[key] = { tag: b.tag.trim(), total: 0, entries: [] };
    groups[key].total += Number(b.amount) || 0;
    groups[key].entries.push(b);
  });
  const groupList = Object.values(groups).sort((a, b) => a.tag.localeCompare(b.tag));

  return (
    <div className="sheet-panel wide">
      <h3>Bonus thématiques</h3>
      <p className="hint small">
        Ajoutez ici les bonus spécifiques repérés dans vos actions (ex. « Nature », « Phase de repos », « Combat en mer »…).
        Les bonus partageant le même intitulé se cumulent automatiquement, avec un total prêt à copier pour vos jets.
        Associez un bonus à une statistique pour pouvoir l'activer/désactiver temporairement sur votre hexaèdre.
      </p>

      {groupList.length > 0 && (
        <div className="thematic-groups">
          {groupList.map((g) => (
            <div className="thematic-group" key={g.tag}>
              <div className="thematic-group-head">
                <span className="thematic-group-tag">{g.tag}</span>
                <span className="thematic-group-total">
                  {g.total >= 0 ? "+" : ""}{g.total}
                  <RollCopyButton formula={`/roll 1d100+${g.total}`} title={`Copier le jet avec le bonus cumulé "${g.tag}" (${g.total >= 0 ? "+" : ""}${g.total})`} />
                </span>
              </div>
              <div className="thematic-entries">
                {g.entries.map((e) => {
                  const key = "tb:" + e.id;
                  const isOn = !!toggles[key];
                  return (
                    <div className="thematic-entry" key={e.id}>
                      <span>
                        {e.amount >= 0 ? "+" : ""}{e.amount}{e.stat ? ` ${e.stat}` : ""}{e.note ? ` — ${e.note}` : ""}
                      </span>
                      {e.stat && (
                        <label className="thematic-toggle">
                          <input type="checkbox" checked={isOn} onChange={() => toggleStatBonus(e)} /> Actif sur {e.stat}
                        </label>
                      )}
                      <button className="icon-btn" onClick={() => remove(e)}>✕</button>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="purchase-form-row" style={{ marginTop: 10 }}>
        <input placeholder="Tag (ex : Nature, Phase de repos…)" value={tag} onChange={(e) => setTag(e.target.value)} />
        <label className="purchase-cost">Valeur
          <input type="number" value={amount} onChange={(e) => setAmount(parseInt(e.target.value || "0", 10))} />
        </label>
        <select value={stat} onChange={(e) => setStat(e.target.value)}>
          <option value="">Aucune stat (bonus générique)</option>
          {STATS.map((s) => <option key={s.key} value={s.key}>{s.key} — {s.name}</option>)}
        </select>
        <input placeholder="Note (optionnel)" value={note} onChange={(e) => setNote(e.target.value)} style={{ flex: 1 }} />
        <button className="btn ghost small" onClick={add}>+ Ajouter</button>
      </div>
    </div>
  );
}

/* --- Onglet Actions : généré depuis les tableaux de niveaux de la classe --- */

/* --- Panneau de dépense d'XP : achat de niveaux (multiclasse) --- */

function XpShopPage({ character, race, onChange, onBack }) {
  const classes = character.classes || [];
  const spent = totalSpentXp(character);
  const available = (character.xp || 0) - spent;
  const [pickerOpen, setPickerOpen] = useState(false);

  function updateEntry(id, patch) {
    onChange({ classes: classes.map((c) => (c.id === id ? { ...c, ...patch } : c)) });
  }
  function buyLevel(entry) {
    const cost = classLevelCost(entry.level + 1) - classLevelCost(entry.level);
    if (entry.level >= MAX_LEVEL || cost > available) return;
    updateEntry(entry.id, { level: entry.level + 1 });
  }
  function sellLevel(entry) {
    if (entry.level <= 1) return;
    updateEntry(entry.id, { level: entry.level - 1 });
  }
  function addClass(classId) {
    onChange({ classes: [...classes, emptyClassEntry(classId)] });
    setPickerOpen(false);
  }
  function spendExtra(cost) {
    onChange({ xpSpentExtra: (character.xpSpentExtra || 0) + Math.max(0, cost) });
  }

  return (
    <div className="tab-panel xp-shop">
      <button className="btn ghost" onClick={onBack}>← Retour à la fiche</button>
      <h2 style={{ marginTop: 14 }}>Dépenser de l'XP</h2>
      <div className="xp-spend-summary">
        <span>XP totale : <strong>{character.xp || 0}</strong></span>
        <span>Dépensée : <strong>{spent}</strong></span>
        <span>Disponible : <strong className={available < 0 ? "sb-down" : ""}>{available}</strong></span>
      </div>

      <div className="xp-shop-section">
        <h3>Niveaux de classe</h3>
        <p className="hint small">Achetez un niveau dans une classe existante, ou ajoutez une nouvelle classe pour multiclasser.</p>
        <div className="xp-spend-list">
          {classes.map((entry) => {
            const cls = CLASSES.find((c) => c.id === entry.classId);
            const levelData = cls ? CLASS_LEVELS[cls.id] : null;
            const nextCost = classLevelCost(entry.level + 1) - classLevelCost(entry.level);
            const canBuy = entry.level < MAX_LEVEL && nextCost <= available;
            const subclassUnlocked = entry.level >= 6;
            const futureActions = entry.subclass ? buildActionListFull(entry.classId, entry.subclass).filter((a) => a.unlockLevel > entry.level) : [];
            return (
              <div className="xp-spend-entry" key={entry.id}>
                <div className="xp-spend-row">
                  <ClassIcon classId={entry.classId} size={24} />
                  <span className="xp-spend-name">{cls?.name}{entry.subclass ? ` — ${entry.subclass}` : ""}</span>
                  <span className="xp-spend-level">Niv. {entry.level}</span>
                  <button className="btn ghost small" onClick={() => sellLevel(entry)} disabled={entry.level <= 1}>−1</button>
                  <button className="btn primary small" onClick={() => buyLevel(entry)} disabled={!canBuy}>
                    +1 niveau ({nextCost} XP)
                  </button>
                </div>
                {cls && cls.subclasses.length > 0 && (
                  !entry.subclass ? (
                    subclassUnlocked ? (
                      <div className="subclass-preview-grid" style={{ marginTop: 8 }}>
                        {cls.subclasses.map((s) => {
                          const info = levelData && levelData.ranks ? levelData.ranks.subclasses.find((x) => x.name === s) : null;
                          return (
                            <div key={s} className="subclass-preview-card selectable" onClick={() => updateEntry(entry.id, { subclass: s })}>
                              <div className="subclass-preview-name">{s}</div>
                              {info?.flavor && <p className="hint small">{info.flavor}</p>}
                            </div>
                          );
                        })}
                      </div>
                    ) : (
                      <p className="hint small" style={{ margin: "4px 0 0" }}>Sous-classe disponible à partir du niveau 6.</p>
                    )
                  ) : (
                    <div className="subclass-block" style={{ marginTop: 8 }}>
                      <div className="subclass-chosen-head">
                        <span className="hint small" style={{ margin: 0 }}>École : <strong>{entry.subclass}</strong></span>
                        <button className="btn ghost small" onClick={() => updateEntry(entry.id, { subclass: null })}>Changer d'école</button>
                      </div>
                      {futureActions.length > 0 && (
                        <>
                          <h3>Évolutions futures</h3>
                          <div className="level-table">
                            {futureActions.map((a, i) => (
                              <div className="level-row locked-preview" key={i}>
                                <span className="level-num">{a.source}</span>
                                <span className="level-name">{a.name}</span>
                                <span className="level-type">{a.type}</span>
                                <p className="level-desc">{a.desc}</p>
                              </div>
                            ))}
                          </div>
                        </>
                      )}
                    </div>
                  )
                )}
              </div>
            );
          })}
        </div>
        <button className="btn ghost small" onClick={() => setPickerOpen((v) => !v)}>+ Ajouter une classe (multiclasse)</button>
        {pickerOpen && (
          <div className="class-picker-grid" style={{ marginTop: 10 }}>
            {CLASSES.filter((c) => !classes.some((e) => e.classId === c.id) && !isClassBlockedForRace(c.id, race)).map((c) => (
              <button key={c.id} className="class-picker-card" onClick={() => addClass(c.id)}>
                <ClassIcon classId={c.id} size={28} />
                <span>{c.name}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="xp-shop-section">
        <h3>Compétences</h3>
        <p className="hint small">Achetez une nouvelle compétence avec votre XP (coût à fixer avec le MJ). Elle apparaîtra dans l'onglet Actions.</p>
        <SkillPurchaseForm available={available} onBuy={(skill, cost) => {
          const category = skill.category;
          const key = category === "Passif" ? "skillsPassive" : "skillsActive";
          const list = character[key] || [];
          onChange({ [key]: [...list, skill] });
          spendExtra(cost);
        }} />
      </div>

      {classes.some((c) => c.classId === "mage") && (
        <div className="xp-shop-section">
          <h3>Sorts</h3>
          <p className="hint small">Apprenez un nouveau sort dans le domaine de l'une de vos classes magiques (coût à fixer avec le MJ).</p>
          <SpellPurchaseForm character={character} available={available} onBuy={(spell, cost) => {
            const spells = character.spells || [];
            onChange({ spells: [...spells, spell] });
            spendExtra(cost);
          }} />
        </div>
      )}
    </div>
  );
}

function SkillPurchaseForm({ available, onBuy }) {
  const [search, setSearch] = useState("");
  const [nom, setNom] = useState("");
  const [category, setCategory] = useState("Passif");
  const [cost, setCost] = useState(0);
  const [notes, setNotes] = useState("");
  const canBuy = nom.trim().length > 0 && cost >= 0 && cost <= available;

  const results = search.trim().length > 0
    ? SKILLS_CATALOG.filter((s) => s.nom.toLowerCase().includes(search.trim().toLowerCase()))
    : SKILLS_CATALOG;

  function pick(skill) {
    setNom(skill.nom);
    setCategory(skill.category);
    setNotes(skill.notes);
    setSearch("");
  }

  function buy() {
    if (!canBuy) return;
    onBuy({ id: "c" + Math.random().toString(36).slice(2, 9), nom, niveau: "", notes, category }, cost);
    setNom(""); setCost(0); setNotes("");
  }

  return (
    <div className="purchase-form">
      <div className="catalog-search">
        <input placeholder="🔍 Rechercher dans le catalogue de compétences…" value={search} onChange={(e) => setSearch(e.target.value)} />
        {search.trim().length > 0 && (
          <div className="catalog-results">
            {results.length > 0 ? results.map((s) => (
              <button key={s.nom} className="catalog-result" onClick={() => pick(s)}>
                <strong>{s.nom}</strong>
                <span>{s.category}</span>
              </button>
            )) : <p className="hint small" style={{ padding: 8 }}>Aucun résultat — vous pouvez saisir un nom libre ci-dessous.</p>}
          </div>
        )}
      </div>
      <div className="purchase-form-row">
        <input placeholder="Nom de la compétence" value={nom} onChange={(e) => setNom(e.target.value)} />
        <select value={category} onChange={(e) => setCategory(e.target.value)}>
          {ACTION_CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
        </select>
        <label className="purchase-cost">Coût XP
          <input type="number" min="0" value={cost} onChange={(e) => setCost(Math.max(0, parseInt(e.target.value || "0", 10)))} />
        </label>
      </div>
      <textarea placeholder="Effets" value={notes} onChange={(e) => setNotes(e.target.value)} />
      <button className="btn primary small" onClick={buy} disabled={!canBuy}>Acheter</button>
    </div>
  );
}

function SpellPurchaseForm({ character, available, onBuy }) {
  const mageEntries = (character.classes || []).filter((c) => classGrantsMagic(CLASSES.find((x) => x.id === c.classId)) && c.magicDomain);
  const [entryId, setEntryId] = useState(mageEntries[0]?.id || "");
  const entry = mageEntries.find((e) => e.id === entryId) || mageEntries[0];
  const domainData = entry ? MAGIC_DOMAINS_DATA.find((d) => d.name === entry.magicDomain) : null;
  const known = new Set([
    ...(character.spells || []).map((s) => s.nom),
    ...((character.classes || []).flatMap((c) => (c.freeSpells || []).map((s) => s.nom))),
  ]);
  const available_spells = domainData ? domainData.spells.filter((s) => !known.has(s.nom)) : [];
  const [spellName, setSpellName] = useState("");
  const [cost, setCost] = useState(0);

  if (mageEntries.length === 0) return <p className="hint small">Choisissez d'abord un domaine de magie pour une de vos classes.</p>;

  const chosenSpell = available_spells.find((s) => s.nom === spellName);
  const canBuy = chosenSpell && cost >= 0 && cost <= available;

  function buy() {
    if (!canBuy) return;
    onBuy({ id: "s" + Math.random().toString(36).slice(2, 9), nom: chosenSpell.nom, seuil: chosenSpell.seuil, portee: chosenSpell.portee, effets: chosenSpell.effets }, cost);
    setSpellName(""); setCost(0);
  }

  return (
    <div className="purchase-form">
      {mageEntries.length > 1 && (
        <select value={entry?.id} onChange={(e) => setEntryId(e.target.value)} style={{ marginBottom: 8 }}>
          {mageEntries.map((e) => <option key={e.id} value={e.id}>{e.magicDomain}</option>)}
        </select>
      )}
      <div className="purchase-form-row">
        <select value={spellName} onChange={(e) => setSpellName(e.target.value)}>
          <option value="">— Choisir un sort ({domainData?.name || "domaine"}) —</option>
          {available_spells.map((s) => <option key={s.nom} value={s.nom}>{s.nom} (Seuil {s.seuil})</option>)}
        </select>
        <label className="purchase-cost">Coût XP
          <input type="number" min="0" value={cost} onChange={(e) => setCost(Math.max(0, parseInt(e.target.value || "0", 10)))} />
        </label>
      </div>
      {chosenSpell && <p className="hint small">{chosenSpell.effets}</p>}
      <button className="btn primary small" onClick={buy} disabled={!canBuy}>Apprendre ce sort</button>
    </div>
  );
}

/* --- Onglet Actions : généré depuis les tableaux de niveaux de toutes les classes, fusionné avec les compétences --- */

/** Techniques "hub" activables par interrupteur, dont les niveaux d'amélioration ultérieurs
 *  (qui la mentionnent par son nom) sont listés automatiquement au fur et à mesure qu'ils se
 *  débloquent — ex. la Zone défensive du Clipeum. */
const HUB_TECHNIQUES = ["Zone défensive"];

function TabActions({ character, race, onChange, layers, originIndex }) {
  const classes = character.classes || [];
  const skillsActive = character.skillsActive || [];
  const skillsPassive = character.skillsPassive || [];
  const origin = race && originIndex !== null && originIndex !== undefined ? race.origins[originIndex] : null;

  const classActions = useMemo(() => {
    let all = [];
    const choices = character.classStatChoices || {};
    classes.forEach((entry) => {
      const acts = buildActionList(entry.classId, entry.subclass, entry.level);
      all = all.concat(acts.map((a) => {
        const choice = extractStatChoiceFromText(a.desc);
        return { ...a, sourceLabel: "Classe", statChoice: choice, chosenStat: choice ? choices[a.name] || null : null };
      }));
    });
    HUB_TECHNIQUES.forEach((hubName) => {
      const hub = all.find((a) => a.name === hubName);
      if (hub) {
        hub.isHub = true;
        hub.improvements = all.filter((a) => a.name !== hubName && a.desc && a.desc.toLowerCase().includes(hubName.toLowerCase()));
      }
    });
    return all;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [classes, character.classStatChoices]);

  function toggleHub(name) {
    const toggles = character.activeToggles || {};
    onChange({ activeToggles: { ...toggles, [name]: !toggles[name] } });
  }

  const originActions = useMemo(() => {
    if (!origin) return [];
    return [
      { name: originStatLabel(origin), desc: null, category: "Passif", sourceLabel: "Origine" },
      ...origin.bonuses.map((b) => ({ name: b, desc: null, category: "Passif", sourceLabel: "Origine" })),
    ];
  }, [origin]);

  const skillActions = [
    ...skillsActive.map((s) => ({ ...s, name: s.nom, desc: s.notes, category: s.category || "Action simple", sourceLabel: "Compétence", isSkill: true, listKey: "skillsActive" })),
    ...skillsPassive.map((s) => ({ ...s, name: s.nom, desc: s.notes, category: "Passif", sourceLabel: "Compétence", isSkill: true, listKey: "skillsPassive" })),
  ];

  function addSkill(category) {
    const skill = emptySkill();
    skill.category = category;
    if (category === "Passif") onChange({ skillsPassive: [...skillsPassive, skill] });
    else onChange({ skillsActive: [...skillsActive, skill] });
  }
  function updateSkill(id, listKey, patch) {
    const list = listKey === "skillsPassive" ? skillsPassive : skillsActive;
    onChange({ [listKey]: list.map((s) => (s.id === id ? { ...s, ...patch } : s)) });
  }
  function removeSkill(id, listKey) {
    const list = listKey === "skillsPassive" ? skillsPassive : skillsActive;
    onChange({ [listKey]: list.filter((s) => s.id !== id) });
  }
  function chooseStat(levelName, stat) {
    const choices = character.classStatChoices || {};
    onChange({ classStatChoices: { ...choices, [levelName]: stat } });
  }
  function choosePosture(posture) {
    onChange({ rosacePosture: character.rosacePosture === posture ? null : posture });
  }
  const rosaceInfo = getRosacePostureInfo(character);

  function chooseMercPosture(posture) {
    const current = character.mercPosture;
    const armor = { ...(character.armor || { physique: 0, magique: 0, temporaire: 0, degatPermanent: 0 }) };
    if (current === "defensive") armor.temporaire = Math.max(0, (armor.temporaire || 0) - 2);
    const next = current === posture ? null : posture;
    if (next === "defensive") armor.temporaire = (armor.temporaire || 0) + 2;
    onChange({ mercPosture: next, armor });
  }

  const hasRaceTraits = race && race.traits && race.traits.length > 0;

  if (classes.length === 0 && skillActions.length === 0 && !hasRaceTraits) {
    return <p className="hint">Ajoutez une classe à l'étape "Classes" pour voir ses actions, ou ajoutez une compétence manuellement ci-dessous.</p>;
  }

  return (
    <div className="tab-panel">
      <p className="hint">
        Techniques débloquées par vos classes, traits de race et compétences apprises, classées par type d'action.
      </p>

      {ACTION_CATEGORIES.map((cat) => {
        const fromClasses = classActions.filter((a) => a.category === cat);
        const fromSkills = skillActions.filter((a) => a.category === cat);
        const list = cat === "Passif" ? [...fromSkills, ...fromClasses] : [...fromClasses, ...fromSkills];
        return (
          <React.Fragment key={cat}>
            <div className="action-group">
              <h3>{cat} <span className="action-count">({list.length})</span></h3>
              {cat === "Passif" ? (
                <>
                  {fromSkills.length > 0 && (
                    <>
                      <h4 className="action-subheading">Compétences <span className="action-count">({fromSkills.length})</span></h4>
                      <div className="action-list">{fromSkills.map((a, i) => <ActionCard key={a.id || i} a={a} updateSkill={updateSkill} removeSkill={removeSkill} />)}</div>
                    </>
                  )}
                  {fromClasses.length > 0 && (
                    <>
                      <h4 className="action-subheading">Passifs de classe <span className="action-count">({fromClasses.length})</span></h4>
                      <div className="action-list">{fromClasses.map((a, i) => <ActionCard key={a.id || i} a={a} updateSkill={updateSkill} removeSkill={removeSkill} onChooseStat={chooseStat} onToggleHub={toggleHub} activeToggles={character.activeToggles} onChoosePosture={choosePosture} rosacePosture={character.rosacePosture} rosaceInfo={rosaceInfo} onChooseMercPosture={chooseMercPosture} mercPosture={character.mercPosture} />)}</div>
                    </>
                  )}
                  {originActions.length > 0 && (
                    <>
                      <h4 className="action-subheading">Origine <span className="action-count">({originActions.length})</span></h4>
                      <div className="action-list">{originActions.map((a, i) => <ActionCard key={i} a={a} updateSkill={updateSkill} removeSkill={removeSkill} />)}</div>
                    </>
                  )}
                </>
              ) : (
                list.length > 0 && (
                  <div className="action-list">
                    {list.map((a, i) => <ActionCard key={a.id || i} a={a} updateSkill={updateSkill} removeSkill={removeSkill} onChooseStat={chooseStat} onToggleHub={toggleHub} activeToggles={character.activeToggles} onChoosePosture={choosePosture} rosacePosture={character.rosacePosture} rosaceInfo={rosaceInfo} onChooseMercPosture={chooseMercPosture} mercPosture={character.mercPosture} />)}
                  </div>
                )
              )}
              <button className="btn ghost small" style={{ marginTop: 8 }} onClick={() => addSkill(cat)}>+ Ajouter une compétence en {cat}</button>
            </div>
            {cat === "Phase de repos" && hasRaceTraits && (
              <div className="action-group">
                <h3>Traits de race</h3>
                <TraitList race={race} character={character} onChange={onChange} layers={layers} originIndex={originIndex} />
              </div>
            )}
          </React.Fragment>
        );
      })}
    </div>
  );
}

/** Une carte d'action/compétence/technique, réutilisée pour toutes les catégories de l'onglet Compétences. */
function ActionCard({ a, updateSkill, removeSkill, onChooseStat, onToggleHub, activeToggles, onChoosePosture, rosacePosture, rosaceInfo, onChooseMercPosture, mercPosture }) {
  const isGranted = a.isSkill && !!a.grantedBy;
  const isArtMagie = a.isSkill && a.nom === "Art de la magie";
  const hubOn = a.isHub && !!(activeToggles && activeToggles[a.name]);
  const isPostureCard = a.name === "Posture de Rosace";
  const isMercPostureCard = a.name === "Posture adaptable";
  return (
    <div className="action-card">
      <div className="action-card-head">
        {a.isSkill ? (
          isGranted ? (
            <span className="action-name">
              {a.name}{a.niveau ? <span className="action-level-badge">N°{a.niveau}</span> : null}
            </span>
          ) : (
            <>
              <input className="action-name-input" value={a.name} placeholder="Nom de la compétence"
                onChange={(e) => updateSkill(a.id, a.listKey, { nom: e.target.value })} />
              <input className="action-level-input" value={a.niveau || ""} placeholder="N°"
                onChange={(e) => updateSkill(a.id, a.listKey, { niveau: e.target.value })} />
            </>
          )
        ) : (
          <span className="action-name">{a.name}</span>
        )}
        <span className="action-source-tag">{a.isSkill ? (isGranted ? "Race/Classe" : "Compétence") : a.sourceLabel}{a.source ? ` · ${a.source}` : ""}</span>
        {a.isSkill && !isGranted && <button className="icon-btn" onClick={() => removeSkill(a.id, a.listKey)}>✕</button>}
      </div>
      {a.domain && <div className="action-domain-sub">Domaine : {a.domain}</div>}
      {a.isSkill ? (
        isGranted ? (
          a.notes && <p className="action-desc">{a.notes}</p>
        ) : (
          <textarea className="action-desc-input" placeholder="Effets" value={a.desc || ""}
            onChange={(e) => updateSkill(a.id, a.listKey, { notes: e.target.value })} />
        )
      ) : (
        a.desc && <p className="action-desc">{a.desc}</p>
      )}
      {isArtMagie && a.niveau && <SpellCastHelper level={parseInt(a.niveau, 10) || 1} />}
      {a.statChoice && (
        <div className="stat-choice-row">
          <span className="hint small" style={{ margin: 0 }}>Choisissez la statistique bonifiée :</span>
          {a.statChoice.options.map((opt) => (
            <button key={opt.stat} className={"chip" + (a.chosenStat === opt.stat ? " selected" : "")}
              onClick={() => onChooseStat(a.name, opt.stat)}>
              +{opt.amount}% {opt.stat}
            </button>
          ))}
        </div>
      )}
      {a.isHub && (
        <div className="trait-mechanic">
          <label className="trait-toggle">
            <input type="checkbox" checked={hubOn} onChange={() => onToggleHub(a.name)} /> Active
          </label>
          {a.improvements.length > 0 && (
            <div style={{ marginTop: 8 }}>
              <span className="hint small" style={{ margin: 0 }}>Améliorations débloquées :</span>
              <ul className="plain-list">
                {a.improvements.map((imp, i) => (
                  <li key={i}><strong>{imp.name}</strong> (niv. {imp.unlockLevel}) — {imp.desc}</li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}
      {isPostureCard && (
        <div className="trait-mechanic">
          <p className="hint small" style={{ margin: "0 0 6px" }}>Choisissez votre posture active :</p>
          <div className="chip-row">
            {[["brutal", "Flux Brutal"], ["stable", "Flux Stable"], ["conduit", "Flux Conduit"]].map(([val, label]) => (
              <button key={val} className={"chip" + (rosacePosture === val ? " selected" : "")} onClick={() => onChoosePosture(val)}>{label}</button>
            ))}
          </div>
          {rosacePosture === "brutal" && rosaceInfo?.tier && (
            <p className="hint small" style={{ margin: "8px 0 0" }}>
              <strong>{rosaceInfo.tier.label}</strong> : +{rosaceInfo.tier.degats} dégâts à tous vos sorts (déjà appliqué dans l'onglet Sorts). Pensez à lancer <strong>+{rosaceInfo.tier.dice}d10</strong> supplémentaire(s) pour déterminer si un phénomène magique survient.
            </p>
          )}
          {rosacePosture === "stable" && rosaceInfo && (
            <p className="hint small" style={{ margin: "8px 0 0" }}>{rosaceInfo.stableNote}</p>
          )}
          {rosacePosture === "conduit" && rosaceInfo && (
            <p className="hint small" style={{ margin: "8px 0 0" }}>{rosaceInfo.conduitNote}</p>
          )}
        </div>
      )}
      {isMercPostureCard && (
        <div className="trait-mechanic">
          <p className="hint small" style={{ margin: "0 0 6px" }}>Choisissez votre posture pour ce tour :</p>
          <div className="chip-row">
            {[["offensive", "Offensive (+2 dégâts)"], ["defensive", "Défensive (+2 armure temp.)"], ["mobile", "Mobile (+5m déplacement)"]].map(([val, label]) => (
              <button key={val} className={"chip" + (mercPosture === val ? " selected" : "")} onClick={() => onChooseMercPosture(val)}>{label}</button>
            ))}
          </div>
          {mercPosture === "offensive" && <p className="hint small" style={{ margin: "8px 0 0" }}>+2 dégâts déjà appliqué dans le tableau Armes.</p>}
          {mercPosture === "defensive" && <p className="hint small" style={{ margin: "8px 0 0" }}>+2 armure temporaire déjà appliqué dans l'Armure.</p>}
          {mercPosture === "mobile" && <p className="hint small" style={{ margin: "8px 0 0" }}>+5m de déplacement ce tour (non reflété automatiquement sur la Vitesse, qui est permanente).</p>}
        </div>
      )}
    </div>
  );
}

/** Aide au lancer de sort : choisit combien de d10 lancer (1 à N, N = niveau de la compétence
 *  Art de la magie), pour comparer le résultat au seuil du sort. */
function SpellCastHelper({ level }) {
  const [count, setCount] = useState(level);
  const options = Array.from({ length: level }).map((_, i) => i + 1);
  return (
    <div className="spell-cast-helper">
      <span className="hint small" style={{ margin: 0 }}>Lancer un sort :</span>
      <select value={count} onChange={(e) => setCount(parseInt(e.target.value, 10))}>
        {options.map((n) => <option key={n} value={n}>{n}d10</option>)}
      </select>
      <RollCopyButton formula={`/roll ${count}d10`} title={`Copier le jet de ${count}d10 pour lancer un sort`} />
    </div>
  );
}

/** Paliers de la jauge d'Ivresse (Mercenaire — Groupe des Trois Futs). */
const IVRESSE_TIERS = [
  { min: 0, max: 3, name: "Sobre", note: "Aucun bonus ou malus." },
  { min: 4, max: 6, name: "Échauffement", note: "+5% CHA, immunité à la peur, +2 dégâts." },
  { min: 7, max: 9, name: "Ivresse troublée", note: "-10% AGI, -5% FOR, +10m de portée de déplacement." },
  { min: 10, max: 15, name: "Ivresse combative", note: "+8 dégâts, +4 armure temporaire, +5% FOR, -10% INT, -10% PER." },
  { min: 16, max: 20, name: "Ivresse titubante", note: "+2 dégâts, -10m de portée de déplacement, +20% AGI, -20% FOR, +10% Chance." },
  { min: 21, max: 21, name: "Frénésie éthylique", note: "+12 dégâts, +10% FOR, dégâts subis divisés par deux, immunité à la peur, impossible d'utiliser une compétence." },
  { min: 22, max: 23, name: "Démence alcoolisée", note: "+20 dégâts, +20% FOR, +6 armure temporaire, impossible d'utiliser une compétence, dégâts subis doublés. Chaque attaque : 1d4, sur 3-4 elle cible l'allié le plus proche à moins de 5m." },
  { min: 24, max: Infinity, name: "Blackout", note: "Chaque tour : jet de CON avec -30%. Échec = assommé ce tour. Réussite = PI -1d20 et malus de 10% (cumulable) jusqu'au repos. 3 échecs = évanoui." },
];
function getIvresseTier(pi) {
  return IVRESSE_TIERS.find((t) => pi >= t.min && pi <= t.max) || IVRESSE_TIERS[0];
}
/** Extrait tous les modificateurs de statistique (+/-X% STAT) d'un texte, ex. le palier
 *  "+5% FOR, -10% INT, -10% PER" en 3 entrées distinctes. */
function parseAllStatMods(text) {
  const mods = [];
  const re = /([+-])(\d+)\s*%\s*(FOR|AGI|CON|INT|CHA|PER)\b/gi;
  let m;
  while ((m = re.exec(text || ""))) {
    mods.push({ stat: m[3].toUpperCase(), amount: (m[1] === "-" ? -1 : 1) * parseInt(m[2], 10) });
  }
  return mods;
}
const ALCOOLS = [
  { nom: "Bière", pi: 2, prix: "Gratuit" },
  { nom: "Vin", pi: 6, prix: "1 pa" },
  { nom: "Hydromel", pi: 8, prix: "2 pa" },
  { nom: "Rhum", pi: 10, prix: "6 pa" },
  { nom: "Alcool artisanale", pi: 15, prix: "12 pa" },
  { nom: "Eau", pi: -1, prix: "Gratuit" },
];

/** Onglet dédié à la mécanique d'Ivresse (Mercenaire — Groupe des Trois Futs). Boire ajuste les
 *  PI et réconcilie automatiquement les bonus/malus de statistique du palier atteint (les autres
 *  effets du palier — dégâts, armure, déplacement, Chance — restent des rappels à appliquer
 *  soi-même, trop variés pour être fiabilisés automatiquement). */
function TabAlcoolemie({ character, onChange }) {
  const pi = character.pointsIvresse || 0;
  const tier = getIvresseTier(pi);

  function setPI(newPI) {
    const clamped = Math.max(0, newPI);
    const oldTier = getIvresseTier(pi);
    const newTier = getIvresseTier(clamped);
    let temp = { ...(character.tempBonuses || emptyBonuses()) };
    if (oldTier !== newTier) {
      parseAllStatMods(oldTier.note).forEach((m) => { temp[m.stat] = (temp[m.stat] || 0) - m.amount; });
      parseAllStatMods(newTier.note).forEach((m) => { temp[m.stat] = (temp[m.stat] || 0) + m.amount; });
    }
    onChange({ pointsIvresse: clamped, tempBonuses: temp });
  }
  function startCombat() { setPI(0); }

  return (
    <div className="tab-panel">
      <h3>Jauge d'Ivresse</h3>
      <p className="hint small">
        Réputation en taverne +5, réduction de 50% sur vos consommations. La jauge revient à 0 à chaque début de combat.
        Les bonus/malus de statistique du palier atteint sont appliqués automatiquement à vos bonus temporaires ; les autres effets (dégâts, armure, déplacement, Chance…) restent à appliquer vous-même.
      </p>
      <div className="ivresse-display">
        <div className="ivresse-pi">
          <button className="btn ghost small" onClick={() => setPI(pi - 1)}>−1 PI</button>
          <span className="ivresse-pi-value">{pi} PI</span>
          <button className="btn ghost small" onClick={() => setPI(pi + 1)}>+1 PI</button>
        </div>
        <div className="ivresse-tier">
          <strong>{tier.name}</strong>
          <p className="hint small" style={{ margin: "4px 0 0" }}>{tier.note}</p>
          {(() => {
            const mods = parseAllStatMods(tier.note);
            if (mods.length === 0) return null;
            return (
              <p className="hint small" style={{ margin: "6px 0 0", color: "var(--accent)" }}>
                ✓ Appliqué à vos bonus temporaires : {mods.map((m) => `${m.amount >= 0 ? "+" : ""}${m.amount}% ${m.stat}`).join(", ")}
                {" "}(visible dans l'Aperçu, tableau des statistiques).
              </p>
            );
          })()}
        </div>
      </div>
      <button className="btn primary small" onClick={startCombat} style={{ marginTop: 10 }}>⚔ Début de combat (PI → 0)</button>
      <button className="btn ghost small" onClick={() => {
        const temp = { ...(character.tempBonuses || emptyBonuses()) };
        const allIvresseStats = new Set();
        IVRESSE_TIERS.forEach((t) => parseAllStatMods(t.note).forEach((m) => allIvresseStats.add(m.stat)));
        allIvresseStats.forEach((stat) => { temp[stat] = 0; });
        parseAllStatMods(tier.note).forEach((m) => { temp[m.stat] = m.amount; });
        onChange({ tempBonuses: temp });
      }} style={{ marginTop: 10, marginLeft: 8 }}>↻ Recalibrer les bonus du palier actuel</button>

      <h3 style={{ marginTop: 20 }}>Boire</h3>
      <div className="ivresse-drinks">
        {ALCOOLS.map((a) => (
          <button key={a.nom} className="btn ghost small" onClick={() => setPI(pi + a.pi)}>
            {a.nom} ({a.pi >= 0 ? "+" : ""}{a.pi} PI · {a.prix})
          </button>
        ))}
      </div>

      <h3 style={{ marginTop: 20 }}>Tous les paliers</h3>
      <div className="ivresse-tier-list">
        {IVRESSE_TIERS.map((t) => (
          <div key={t.name} className={"ivresse-tier-row" + (t === tier ? " active" : "")}>
            <span className="ivresse-tier-range">{t.max === Infinity ? `${t.min}+` : `${t.min}–${t.max}`} PI</span>
            <span className="ivresse-tier-name">{t.name}</span>
            <span className="hint small">{t.note}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

function TabSpells({ character, onChange }) {
  const allSpells = character.spells || [];
  const spells = allSpells.filter((s) => !s.grantedBy);
  const grantedSpells = allSpells.filter((s) => s.grantedBy);
  const classes = character.classes || [];
  const mageEntries = classes.filter((c) => classGrantsMagic(CLASSES.find((x) => x.id === c.classId)) && (c.freeSpells || []).length > 0);
  function update(id, patch) { onChange({ spells: allSpells.map((s) => (s.id === id ? { ...s, ...patch } : s)) }); }
  function add() { onChange({ spells: [...allSpells, emptySpell()] }); }
  function remove(id) { onChange({ spells: allSpells.filter((s) => s.id !== id) }); }

  const mdgLevel = mageDeGuerreLevel(character);
  const sigDomain = signatureSpellDomain(character);
  const sigDomainData = sigDomain ? MAGIC_DOMAINS_DATA.find((d) => d.name === sigDomain) : null;

  return (
    <div className="tab-panel">
      {mdgLevel >= 14 && (
        <div className="sheet-panel wide">
          <h3>Sort signature (Mage de Guerre)</h3>
          <p className="hint small">
            Palier{mdgLevel >= 30 ? " IV" : mdgLevel >= 25 ? " III" : mdgLevel >= 23 ? " II" : " I"} actif —
            {mdgLevel >= 14 && " seuil -4"}{mdgLevel >= 23 && ", +5m portée (même en contact)"}{mdgLevel >= 25 && ", castable en action simple"}{mdgLevel >= 30 && ", 2×/jour gratuit en équilibré"}.
          </p>
          {sigDomainData ? (
            <select value={character.signatureSpellName || ""} onChange={(e) => onChange({ signatureSpellName: e.target.value || null })}>
              <option value="">— Choisir votre sort signature ({sigDomain}) —</option>
              {sigDomainData.spells.map((sp) => <option key={sp.nom} value={sp.nom}>{sp.nom}</option>)}
            </select>
          ) : (
            <p className="hint small">Choisissez d'abord un domaine de magie pour votre classe Mage.</p>
          )}
        </div>
      )}

      <h3>Tableau récapitulatif</h3>
      <SpellTables character={character} showDesc={true} />

      {mageEntries.map((entry) => (
        <div key={entry.id}>
          <h3>Sorts gratuits de départ ({entry.magicDomain})</h3>
          <div className="spell-list">
            {(entry.freeSpells || []).map((sp) => (
              <div className="spell-card" key={sp.nom}>
                <div className="spell-row-top">
                  <span className="spell-name-readonly">{sp.nom}</span>
                  <span className="mini-tag"><RuleTerm term="seuil">Seuil</RuleTerm> {sp.seuil}</span>
                  <span className="mini-tag"><RuleTerm term="portee">Portée</RuleTerm> {sp.portee}</span>
                </div>
                <p className="action-desc">{sp.effets}</p>
              </div>
            ))}
          </div>
        </div>
      ))}
      {grantedSpells.length > 0 && (
        <div>
          <h3>Sorts accordés par la race</h3>
          <p className="hint small">Obtenus automatiquement via votre race — non modifiables ici.</p>
          <div className="spell-list">
            {grantedSpells.map((sp) => (
              <div className="spell-card" key={sp.id}>
                <div className="spell-row-top">
                  <span className="spell-name-readonly">{sp.nom}</span>
                  {sp.grantedBy === "race-auto" && <span className="mini-tag improved-tag">Amélioré</span>}
                  <span className="mini-tag"><RuleTerm term="seuil">Seuil</RuleTerm> {sp.seuil}</span>
                  <span className="mini-tag"><RuleTerm term="portee">Portée</RuleTerm> {sp.portee}</span>
                </div>
                <p className="action-desc">{sp.effets}</p>
              </div>
            ))}
          </div>
        </div>
      )}
      <h3>Sorts appris</h3>
      <p className="hint small">Ajoutez ici tous les sorts appris au fil de l'aventure.</p>
      <div className="spell-list">
        {spells.map((s) => (
          <div className="spell-card" key={s.id}>
            <div className="spell-row-top">
              <input className="spell-name" placeholder="Nom du sort" value={s.nom} onChange={(e) => update(s.id, { nom: e.target.value })} />
              <label><RuleTerm term="seuil">Seuil</RuleTerm> <input className="mini-input" value={s.seuil} onChange={(e) => update(s.id, { seuil: e.target.value })} /></label>
              <label><RuleTerm term="portee">Portée</RuleTerm> <input className="mini-input" value={s.portee} onChange={(e) => update(s.id, { portee: e.target.value })} /> m</label>
              <button className="icon-btn" onClick={() => remove(s.id)}>✕</button>
            </div>
            <textarea placeholder="Effets" value={s.effets} onChange={(e) => update(s.id, { effets: e.target.value })} />
          </div>
        ))}
      </div>
      <button className="btn ghost small" onClick={add}>+ Ajouter un sort</button>
    </div>
  );
}

/* --- Onglet Inventaire --- */

function TabInventory({ character, onChange }) {
  const inventory = character.inventory || [];
  const currency = character.currency || { cuivre: 0, argent: 0, or: 0, platine: 0 };
  const classes = character.classes || [];
  const [catalog, setCatalog] = useState(null);
  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState("");
  const [adminOpen, setAdminOpen] = useState(false);

  useEffect(() => {
    loadEquipmentCatalog().then(setCatalog);
  }, []);

  function add() { onChange({ inventory: [...inventory, emptyItem()] }); }
  function update(id, patch) { onChange({ inventory: inventory.map((i) => (i.id === id ? { ...i, ...patch } : i)) }); }
  function remove(id) { onChange({ inventory: inventory.filter((i) => i.id !== id) }); }
  function setCurrency(key, v) { onChange({ currency: { ...currency, [key]: Math.max(0, parseInt(v || "0", 10)) } }); }
  function addFromCatalog(item) {
    onChange({ inventory: [...inventory, { id: "i" + Math.random().toString(36).slice(2, 9), nom: item.nom, poids: item.poids, prix: item.prix, type: item.type, description: item.description, equipped: false, slot: null }] });
  }

  /** Équipe/déséquipe un objet. Pour une arme, l'assigne (ou la retire) d'un des 3 emplacements
   *  (Arme 1, Arme 2, Arme légère) et met à jour les champs de l'onglet Aperçu en conséquence. */
  function toggleEquip(item, slot) {
    const weapons = character.weapons && character.weapons.length ? character.weapons : [emptyWeapon(), emptyWeapon(), emptyWeapon()];
    if (isWeaponType(item)) {
      const alreadyOn = item.equipped && item.slot === slot;
      const newWeapons = [...weapons];
      if (item.equipped && item.slot !== null) newWeapons[item.slot] = emptyWeapon(); // libère l'ancien emplacement
      if (!alreadyOn) {
        const parsed = parseWeaponFromItem(item);
        newWeapons[slot] = parsed;
      }
      update(item.id, { equipped: !alreadyOn, slot: alreadyOn ? null : slot });
      onChange({ weapons: newWeapons });
    } else {
      // Armure/bouclier/objet simple : simple bascule équipé/non équipé.
      update(item.id, { equipped: !item.equipped });
    }
  }

  /** Bourse de terre de l'Île Blanche (Elfes Blancs) : la perdre (décocher) applique un malus
   *  de 25% à toutes les statistiques, la retrouver (recocher) le retire. */
  function toggleBourseTerre(item) {
    const nowPossessed = !item.equipped;
    const temp = { ...(character.tempBonuses || emptyBonuses()) };
    STATS.forEach((s) => { temp[s.key] = (temp[s.key] || 0) + (nowPossessed ? 25 : -25); });
    onChange({
      inventory: inventory.map((i) => (i.id === item.id ? { ...i, equipped: nowPossessed } : i)),
      tempBonuses: temp,
    });
  }

  const startingEquipment = useMemo(() => {
    return classes.map((entry) => {
      if (!entry.subclass) return null;
      const data = CLASS_LEVELS[entry.classId];
      const info = data && data.ranks ? data.ranks.subclasses.find((s) => s.name === entry.subclass) : null;
      return info?.equipment ? { subclass: entry.subclass, equipment: info.equipment } : null;
    }).filter(Boolean);
  }, [classes]);

  const types = catalog ? [...new Set(catalog.map((i) => i.type))].sort() : [];
  const filteredCatalog = (catalog || []).filter((i) =>
    (!typeFilter || i.type === typeFilter) &&
    (!search.trim() || i.nom.toLowerCase().includes(search.trim().toLowerCase()))
  );

  return (
    <div className="tab-panel">
      {startingEquipment.map((eq) => (
        <div className="sheet-panel wide" key={eq.subclass}>
          <h3>Équipement de départ ({eq.subclass})</h3>
          <ul className="plain-list">
            {eq.equipment.split("|").map((item, i) => <li key={i}>{item.trim()}</li>)}
          </ul>
          <p className="hint small">Sélectionnez les objets correspondants ci-dessous dans le catalogue.</p>
        </div>
      ))}

      <h3>Monnaie</h3>
      <div className="currency-row">
        {[["cuivre", "pc"], ["argent", "pa"], ["or", "po"], ["platine", "pp"]].map(([k, unit]) => (
          <label key={k} className="currency-field">
            {k.charAt(0).toUpperCase() + k.slice(1)}
            <input type="number" min="0" value={currency[k]} onChange={(e) => setCurrency(k, e.target.value)} />
            <span>{unit}</span>
          </label>
        ))}
      </div>

      <div className="equipment-catalog-block">
        <div className="equipment-catalog-head">
          <h3 style={{ margin: 0 }}>Catalogue d'équipement</h3>
          <button className="btn ghost small" onClick={() => setAdminOpen((v) => !v)}>⚙ Gérer le catalogue (MJ)</button>
        </div>
        {adminOpen && <EquipmentAdminPanel catalog={catalog} setCatalog={setCatalog} />}

        {catalog === null ? (
          <p className="hint small">Chargement du catalogue…</p>
        ) : catalog.length === 0 ? (
          <p className="hint small">Le catalogue est vide pour le moment — le MJ peut l'importer via "⚙ Gérer le catalogue".</p>
        ) : (
          <>
            <div className="catalog-filter-row">
              <input placeholder="🔍 Rechercher un objet…" value={search} onChange={(e) => setSearch(e.target.value)} />
              <select value={typeFilter} onChange={(e) => setTypeFilter(e.target.value)}>
                <option value="">Tous les types</option>
                {types.map((t) => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>
            <div className="catalog-item-list">
              {filteredCatalog.map((item) => (
                <div className="catalog-item-row" key={item.id}>
                  <div>
                    <strong>{item.nom}</strong>
                    <span className="catalog-item-type">{item.type}</span>
                    {item.description && <p className="hint small" style={{ margin: "2px 0 0" }}>{item.description}</p>}
                  </div>
                  <span className="catalog-item-meta">{item.poids ? `${item.poids} kg` : ""} {item.prix ? `· ${item.prix}` : ""}</span>
                  <button className="btn ghost small" onClick={() => addFromCatalog(item)}>+ Ajouter</button>
                </div>
              ))}
              {filteredCatalog.length === 0 && <p className="hint small">Aucun objet ne correspond à la recherche.</p>}
            </div>
          </>
        )}
      </div>

      <h3>Objets possédés</h3>
      <div className="inventory-list">
        {inventory.map((it) => {
          const weaponItem = isWeaponType(it);
          const armorItem = isArmorType(it);
          return (
            <div className={"inventory-item-row" + (it.equipped ? " equipped" : "")} key={it.id}>
              <div className="inventory-item-top">
                <input className="inventory-item-name" value={it.nom} onChange={(e) => update(it.id, { nom: e.target.value })} />
                <span className="inventory-item-readonly">{it.poids || "—"}</span>
                <span className="inventory-item-readonly">{it.prix || "—"}</span>
                <button className="icon-btn" onClick={() => remove(it.id)}>✕</button>
              </div>
              {(it.type || it.description) && (
                <div className="inventory-item-stats">
                  {it.type && <span className="catalog-item-type">{it.type}</span>}
                  {it.description && <span className="hint small">{it.description}</span>}
                </div>
              )}
              {it.note && <p className="hint small" style={{ margin: "4px 0 0" }}>Note : {it.note}</p>}
              {weaponItem && (
                <div className="equip-row">
                  <span className="hint small" style={{ margin: 0 }}>Équiper vers :</span>
                  {[[0, "Arme 1"], [1, "Arme 2"], [2, "Arme légère"]].map(([slotIdx, label]) => (
                    <button
                      key={slotIdx}
                      className={"chip" + (it.equipped && it.slot === slotIdx ? " selected" : "")}
                      onClick={() => toggleEquip(it, slotIdx)}
                    >{label}</button>
                  ))}
                </div>
              )}
              {armorItem && (
                <label className="equip-toggle">
                  <input type="checkbox" checked={!!it.equipped} onChange={() => toggleEquip(it)} /> Équipé (ajouté à l'armure)
                </label>
              )}
              {it.isBourseTerre && (
                <label className="equip-toggle">
                  <input type="checkbox" checked={!!it.equipped} onChange={() => toggleBourseTerre(it)} />
                  {it.equipped ? "Possédée (aucun malus)" : "Perdue — malus de 25% à toutes les stats actif"}
                </label>
              )}
            </div>
          );
        })}
      </div>
      <AddItemForm onAdd={(item) => onChange({ inventory: [...inventory, item] })} />
    </div>
  );
}

/** Formulaire d'ajout d'un objet libre, avec des champs différents selon la catégorie choisie
 *  (Arme / Armure / Autre) — les champs de dégâts/armure/portée sont ensuite exploités
 *  automatiquement par le système d'équipement, exactement comme les objets du catalogue. */
function AddItemForm({ onAdd }) {
  const [open, setOpen] = useState(false);
  const [category, setCategory] = useState("arme");
  const [nom, setNom] = useState("");
  const [poids, setPoids] = useState("");
  const [prix, setPrix] = useState("");
  const [degats, setDegats] = useState("");
  const [bonusDegats, setBonusDegats] = useState("");
  const [portee, setPortee] = useState("");
  const [regle, setRegle] = useState("");
  const [armurePhysique, setArmurePhysique] = useState("");
  const [armureMagique, setArmureMagique] = useState("");
  const [slot, setSlot] = useState(null);
  const [note, setNote] = useState("");

  function reset() {
    setNom(""); setPoids(""); setPrix(""); setDegats(""); setBonusDegats(""); setPortee("");
    setRegle(""); setArmurePhysique(""); setArmureMagique(""); setSlot(null); setNote("");
  }

  function submit() {
    if (!nom.trim()) return;
    const base = { id: "i" + Math.random().toString(36).slice(2, 9), nom: nom.trim(), poids, prix, category, note, equipped: false, slot: null };
    let item;
    if (category === "arme") {
      const descBits = [`Dégâts : ${degats || "—"}.`];
      if (portee) descBits.push(`Portée : ${portee}.`);
      if (regle) descBits.push(regle);
      item = { ...base, type: "Arme", degats, bonusDegats, portee, regle, description: descBits.join(" ") };
      if (slot !== null) { item.equipped = true; item.slot = slot; }
    } else if (category === "armure") {
      const descBits = [`Armure : ${armurePhysique || 0}${armureMagique ? ` + ${armureMagique} magique` : ""}.`];
      if (regle) descBits.push(regle);
      item = { ...base, type: "Armure", armurePhysique, armureMagique, regle, description: descBits.join(" ") };
    } else {
      item = { ...base, type: "", description: "" };
    }
    onAdd(item);
    reset();
    setOpen(false);
  }

  if (!open) {
    return <button className="btn ghost small" onClick={() => setOpen(true)}>+ Ajouter un objet</button>;
  }

  return (
    <div className="add-item-form">
      <div className="chip-row">
        {[["arme", "Arme"], ["armure", "Armure"], ["autre", "Autre"]].map(([val, label]) => (
          <button key={val} className={"chip" + (category === val ? " selected" : "")} onClick={() => setCategory(val)}>{label}</button>
        ))}
      </div>

      <div className="purchase-form-row" style={{ marginTop: 8 }}>
        <input placeholder="Nom" value={nom} onChange={(e) => setNom(e.target.value)} />
        <label className="purchase-cost">Poids<input value={poids} onChange={(e) => setPoids(e.target.value)} placeholder="1 kg" /></label>
        <label className="purchase-cost">Prix<input value={prix} onChange={(e) => setPrix(e.target.value)} placeholder="5 pa" /></label>
      </div>

      {category === "arme" && (
        <>
          <div className="purchase-form-row">
            <label className="purchase-cost">Dégâts<input value={degats} onChange={(e) => setDegats(e.target.value)} placeholder="1d8" /></label>
            <label className="purchase-cost">Bonus dégâts<input value={bonusDegats} onChange={(e) => setBonusDegats(e.target.value)} placeholder="+0" /></label>
            <label className="purchase-cost">Portée (si à distance)<input value={portee} onChange={(e) => setPortee(e.target.value)} placeholder="20m" /></label>
          </div>
          <input placeholder="Règle particulière" value={regle} onChange={(e) => setRegle(e.target.value)} style={{ width: "100%" }} />
          <div className="equip-row" style={{ marginTop: 8 }}>
            <span className="hint small" style={{ margin: 0 }}>Équiper vers :</span>
            {[[0, "Arme 1"], [1, "Arme 2"], [2, "Arme légère"], [null, "Non équipée"]].map(([slotIdx, label]) => (
              <button key={label} className={"chip" + (slot === slotIdx ? " selected" : "")} onClick={() => setSlot(slotIdx)}>{label}</button>
            ))}
          </div>
        </>
      )}

      {category === "armure" && (
        <>
          <div className="purchase-form-row">
            <label className="purchase-cost">Armure physique<input value={armurePhysique} onChange={(e) => setArmurePhysique(e.target.value)} placeholder="3" /></label>
            <label className="purchase-cost">Armure magique<input value={armureMagique} onChange={(e) => setArmureMagique(e.target.value)} placeholder="0" /></label>
          </div>
          <input placeholder="Règle spécifique" value={regle} onChange={(e) => setRegle(e.target.value)} style={{ width: "100%" }} />
        </>
      )}

      <input placeholder="Note" value={note} onChange={(e) => setNote(e.target.value)} style={{ width: "100%" }} />

      <div className="equipment-admin-actions">
        <button className="btn primary small" onClick={submit} disabled={!nom.trim()}>Ajouter</button>
        <button className="btn ghost small" onClick={() => { reset(); setOpen(false); }}>Annuler</button>
      </div>
    </div>
  );
}

function EquipmentAdminPanel({ catalog, setCatalog }) {
  const [paste, setPaste] = useState("");
  const [saving, setSaving] = useState(false);
  const sharedCount = catalog ? Math.max(0, catalog.length - DEFAULT_EQUIPMENT_CATALOG.length) : 0;

  async function importPaste() {
    const items = parseEquipmentPaste(paste);
    if (items.length === 0) return;
    setSaving(true);
    await saveEquipmentCatalog(items);
    setCatalog([...DEFAULT_EQUIPMENT_CATALOG, ...items]);
    setSaving(false);
    setPaste("");
  }
  async function clearCatalog() {
    setSaving(true);
    await saveEquipmentCatalog([]);
    setCatalog([...DEFAULT_EQUIPMENT_CATALOG]);
    setSaving(false);
  }

  return (
    <div className="equipment-admin-panel">
      <p className="hint small">
        Réservé au MJ : collez ici les lignes copiées depuis votre Excel (colonnes : Nom, Type, Poids, Prix, Description).
        Ceci s'ajoute au catalogue de base ({DEFAULT_EQUIPMENT_CATALOG.length} objets tirés du livre de règles, toujours présents) —
        l'import <strong>remplace</strong> uniquement vos ajouts précédents ({sharedCount} actuellement) et est visible par tous les joueurs de cet artifact.
      </p>
      <textarea
        className="equipment-paste-area"
        placeholder={"Épée courte\tArme une main\t1.5\t10 po\tDégâts 1d6\nBouclier rond\tBouclier\t3\t5 po\t+2 armure"}
        value={paste}
        onChange={(e) => setPaste(e.target.value)}
      />
      <div className="equipment-admin-actions">
        <button className="btn primary small" onClick={importPaste} disabled={saving || paste.trim().length === 0}>
          {saving ? "Import…" : "Importer (ajoute au catalogue)"}
        </button>
        <button className="btn ghost small" onClick={clearCatalog} disabled={saving}>Retirer mes ajouts (garde le catalogue de base)</button>
      </div>
    </div>
  );
}

